1	/* Optimizer (recommendations, rules, history) and Ad group signals. */
2	(() => {
3	  "use strict";
4	  const SP = window.SP, { $, $$, svg, ICON: I } = SP;
5	  const P = SP.PRODUCTS;
6	  const load = (k, d) => { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } };
7	  const save = (k, v) => localStorage.setItem(k, JSON.stringify(v));
8	  SP.ICON.signal = '<circle cx="12" cy="12" r="9.5"/><path d="M14.8 9.2c-.6-.9-1.6-1.4-2.8-1.4-1.6 0-2.7.9-2.7 2.1 0 2.9 5.6 1.6 5.6 4.3 0 1.3-1.2 2.2-2.9 2.2-1.3 0-2.4-.6-2.9-1.5"/>';
9	  SP.ICON.optimizer = '<path d="M9 18h6M10 21h4M8 14c-4-5-1-12 4-12s8 7 4 12c-1 1-1 2-1 3H9c0-1 0-2-1-3Z"/><path d="m12 6-2 4h3l-2 4"/>';
10	  const swatch = h => `<span class="swatch2" style="--h:${SP.swatchColor(h)}"></span>`;
11	  const money2 = v => `$${v.toFixed(2)}`;
12	  const camp = (i, kind) => `${kind}-${["BROAD", "EXACT", "AUTO"][i % 3]}-RANK - ${P[i % 2].asin}`;
13	  const ag = i => `${P[i % 2].asin} - ${["Broad", "Exact", "Auto"][i % 3]}`;
14	
15	  // ---------- Recommendations (sample) ----------
16	  const BID = [
17	    ["-33% bids if >= 60% ACOS", "training rope with handles", 67.33, null, 0.9, 0.6, 2],
18	    ["Default 30% ACOS keyword bid", "cordless battle rope", 45.74, 30, 0.6, 0.57, 3],
19	    ["Default 30% ACOS keyword bid", "training rope with handles", 31.94, 30, 1.2, 1.11, 3],
20	    ["Default 30% ACOS keyword bid", "weighted training rope", 26.69, 30, 0.9, 0.94, 3],
21	    ["Default 30% ACOS keyword bid", "jump rope for women", 21.34, 30, 0.65, 0.75, 3],
22	  ];
23	  const NEG_TERMS = ["fitness equipment", "fitness equipment", "fitness equipment", "fitness equipment", "home gym equipment", "home gym equipment", "home gym equipment", "home gym equipment", "fitness equipment", "fitness equipment", "battle ropes for exercise", "battle ropes for exercise", "weighted jump rope", "weighted jump rope", "weighted jump rope", "skipping rope", "skipping rope", "rope trainer", "exercise rope", "gym rope", "heavy rope"];
24	  const RECS = [
25	    ...BID.map(([opt, kw, acos, target, from, to, ri], i) => ({
26	      _k: `b${i}`, opt, hue: ri, market: "US", match: "Broad", kw, acos,
27	      solution: `${target ? `Target ACOS: <b>${target}%</b><br>` : ""}${to < from ? "Decrease" : "Increase"} bid: <b>${money2(from)} → ${money2(to)}</b>`,
28	      plain: `${to < from ? "Decrease" : "Increase"} bid ${money2(from)} → ${money2(to)}`, type: "Keyword", campaign: camp(i, "SP"), adgroup: ag(i),
29	    })),
30	    ...NEG_TERMS.map((kw, i) => ({
31	      _k: `n${i}`, opt: "Negate no-sale search terms [ASIN phrase/broad]", hue: 8, market: "US", match: "Exact", kw, acos: null,
32	      solution: "Add keyword as <b>negative exact</b>", plain: "Add keyword as negative exact", type: "Search term", campaign: camp(i + 1, "SP"), adgroup: ag(i + 1),
33	    })),
34	  ];
35	
36	  // ---------- Rules (sample) ----------
37	  const RULES = [
38	    ["-60% bids if >= 100% ACOS", "ACOS: ≥ 100.00%", "Adjust bid by -60%", "Bidding", 0],
39	    ["-50% bids if >= 80% ACOS", "ACOS: ≥ 80.00%", "Adjust bid by -50%", "Bidding", 1],
40	    ["-33% bids if >= 60% ACOS", "ACOS: ≥ 60.00%", "Adjust bid by -33%", "Bidding", 2],
41	    ["Bad Conversions <=5%", "Conversion: 1.00% - 5.00%<br>Spend: ≥ $10.00", "Move bid towards 20% ACOS", "Bidding", 4],
42	    ["Bad Conversions <=5% (7 days)", "Conversion: 1.00% - 5.00%<br>Spend: ≥ $10.00", "Move bid towards 20% ACOS", "Bidding", 4],
43	    ["Good Conversions >= 20%", "Orders: ≥ 3<br>Conversion: ≥ 20.00%", "Move bid towards 40% ACOS", "Bidding", 5],
44	    ["Good Conversions >= 20% (7 days)", "Orders: ≥ 3<br>Conversion: ≥ 20.00%", "Move bid towards 40% ACOS", "Bidding", 5],
45	    ["Default 30% ACOS keyword bid", "Clicks: ≥ 10", "Move bid towards 30% ACOS", "Bidding", 3],
46	    ["Raise bids on strong converters", "Orders: ≥ 5<br>ACOS: ≤ 15.00%", "Adjust bid by +15%", "Bidding", 6],
47	    ["Negate no-sale search terms [ASIN phrase/broad]", "Clicks: ≥ 15<br>Orders: 0", "Add keyword as negative exact", "Negation", 8],
48	    ["Negate no-sale search terms [auto]", "Clicks: ≥ 20<br>Orders: 0", "Add keyword as negative exact", "Negation", 8],
49	    ["Pause keywords with no impressions", "Impressions: 0 (30 days)", "Pause keyword", "Status", 9],
50	  ].map(([name, trigger, solution, type, hue], i) => ({ _k: `r${i}`, name, trigger, solution, type, hue, active: true }));
51	  const HUES = ["#d9534f", "#e06a4e", "#e98a3f", "#3d7fe0", "#8b70cf", "#3aa57b", "#2e9bb5", "#c0407a", "#d9534f", "#6c757d"];
52	  SP.swatchColor = h => HUES[h % HUES.length];
53	
54	  const OPT_KEY = "sp-opt-done", RULE_KEY = "sp-opt-rules";
55	  const done = () => load(OPT_KEY, {});
56	  const fmtTime = t => { const d = new Date(t); return `${SP.dash(d)} ${d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}`; };
57	
58	  SP.pages["/ScaleOptimizer"] = {
59	    title: "Scale Optimizer", noSub: true, section: "optimizer", icon: "optimizer", iconColor: "#8b70cf",
60	    render() {
61	      const pending = RECS.filter(r => !done()[r._k]);
62	      const recGrid = SP.grid({
63	        id: "recs", agPager: true, pageSize: 20, columns: true, cls: "ag",
64	        toolsBefore: `<label class="switch green"><input type="checkbox" checked data-markets><span class="track"></span>All markets</label>`,
65	        cols: [
66	          { key: "_k", label: "Actions", sort: false, muted: false, fmt: k => `<span class="recacts"><button class="pill" data-fix="${k}">Fix once</button><button class="link-plain" data-ignore="${k}">Ignore</button></span>` },
67	          { key: "opt", label: "Optimiser", filter: true, w: 250, fmt: (v, r) => `<span class="optname">${swatch(r.hue)}<span>${SP.esc(v)}</span></span>` },
68	          { key: "market", label: "Marketplace", filter: true, sort: false },
69	          { key: "kw", label: "Target", filter: true, w: 200, fmt: (v, r) => `<span class="mbadge">${r.match}</span> ${SP.esc(v)}` },
70	          { key: "acos", label: "Current ACOS", filter: true, fmt: v => (v == null ? "" : `${v.toFixed(2)}%`) },
71	          { key: "solution", label: "Solution (Action to execute)", sort: false, w: 230, fmt: v => `<span class="sol">${v}</span>` },
72	          { key: "campaign", label: "Campaign Name", filter: true, w: 220 },
73	          { key: "adgroup", label: "Ad Group Name", filter: true, w: 170 },
74	        ],
75	        rows: pending, empty: "No recommendations right now. They refresh daily.",
76	      });
77	      const ruleGrid = SP.grid({
78	        id: "rules", agPager: true, pageSize: 20, columns: true, check: true, cls: "ag",
79	        toolsBefore: `<button class="btn-soft" data-newrule>${svg(I.plus)}Create new</button>`,
80	        tools: `<div class="anchor"><button class="plain-btn bulk" data-bulk disabled>Bulk edit ${SP.caret}</button></div>`,
81	        cols: [
82	          { key: "_k", label: "Actions", sort: false, fmt: k => `<span class="rowacts"><button class="ic-round" data-editrule="${k}" aria-label="Edit">${svg(I.pencil)}</button><button class="ic-round" data-delrule="${k}" aria-label="Delete">${svg(I.trash)}</button></span>` },
83	          { key: "active", label: "Active", filter: true, fmt: (v, r) => `<label class="switch green mini"><input type="checkbox" ${v ? "checked" : ""} data-active="${r._k}" aria-label="Active"><span class="track"></span></label>` },
84	          { key: "hue", label: "Color", sort: false, fmt: h => swatch(h) },
85	          { key: "name", label: "Optimizer name", filter: true, w: 230 },
86	          { key: "trigger", label: "Trigger condition", sort: false, w: 200, fmt: v => v },
87	          { key: "solution", label: "Solution (Action to execute)", filter: true, w: 230 },
88	          { key: "type", label: "Rule type", filter: true },
89	          { key: "ruleName", label: "Rule name", filter: true, w: 360, fmt: (_, r) => {
90	            const label = r.name.replace(' <=5%', '').replace(' >= 20%', '');
91	            const cut = r.solution.match(/Adjust bid by -(\d+)%/);
92	            const description = cut ? `Cut bids by ${cut[1]}% if ACOS >= ${r.trigger.replace(/[^0-9.]/g, '').replace('.00', '')}% and no adjustment in last 7 days` : /Bad Conversions/.test(r.name) ? `Adjust bids to 20% ACOS for ${/7 days/.test(r.name) ? 'recent ' : ''}bad ads with conversion <= 5% and spend >= $10` : /Good Conversions/.test(r.name) ? 'Move bids towards 40% ACOS for good ads with orders >= 3 and conversion >= 20%' : r.solution;
93	            return `<div class="optimizer-rule"><span class="rule-badge"><span aria-hidden="true">⚒</span>${SP.esc(label)}</span><small>${SP.esc(description)}</small></div>`;
94	          } },
95	        ],
96	        rows: load(RULE_KEY, null) || RULES,
97	      });
98	      const hist = SP.grid({
99	        id: "hist", agPager: true, pageSize: 10, columns: true, check: true, cls: "ag",
100	        toolsBefore: "", tools: `<button class="plain-btn bulk" data-revert disabled>Bulk revert</button>`,
101	        cols: [
102	          { key: "created", label: "Created", filter: true, fmt: v => fmtTime(v) },
103	          { key: "opt", label: "Optimizer Name", w: 200 },
104	          { key: "campaign", label: "Campaign Name", filter: true, w: 200 },
105	          { key: "adgroup", label: "Ad Group Name", filter: true, w: 150 },
106	          { key: "type", label: "Item Type", filter: true },
107	          { key: "kw", label: "Changed Item" },
108	          { key: "plain", label: "Performed Action", w: 200 },
109	          { key: "_k", label: "Restore", sort: false, fmt: k => `<button class="pill sm" data-restore="${k}">Restore</button>` },
110	        ],
111	        rows: [], empty: "No records found.",
112	      });
113	      const histPanel = `${SP.panel(`<div class="frow"><label class="ctl"><span>${svg(SP.ICON.calendar, "cal")}</span><input type="date" data-hfrom value="${SP.iso(SP.addDays(SP.today, -30))}" aria-label="Start date"> - <input type="date" data-hto value="${SP.iso(SP.today)}" aria-label="End date"></label><button class="btn-dark" data-hfilter>Filter</button></div>`)}${hist}`;
114	      return `<div class="actions tight"><a class="btn-outline linkbtn" href="/AdGroupSignals">Manage Signals</a></div>
115	        ${SP.tabs("opt", ["Recommendations", "Manage", "History"], 1, "ant")}${SP.panels("opt", [recGrid, ruleGrid, histPanel], 1)}`;
116	    },
117	    wire(root) {
118	      const g = SP._grids;
119	      const refreshRecs = () => { g.recs.rows = RECS.filter(r => !done()[r._k]); SP.refreshGrid("recs"); };
120	      const refreshHist = () => {
121	        const from = new Date(($("[data-hfrom]", root).value || "2000-01-01") + "T00:00:00").getTime();
122	        const to = new Date(($("[data-hto]", root).value || "2999-01-01") + "T23:59:59").getTime();
123	        const d = done();
124	        g.hist.rows = RECS.filter(r => d[r._k] && d[r._k].action === "fix" && d[r._k].t >= from && d[r._k].t <= to).map(r => ({ ...r, created: d[r._k].t }));
125	        g.hist.checked.clear(); SP.refreshGrid("hist"); $("[data-revert]", root).disabled = true;
126	      };
127	      const saveRules = () => save(RULE_KEY, g.rules.rows);
128	      refreshHist();
129	      const mark = (k, action) => { const d = done(); d[k] = { action, t: Date.now() }; save(OPT_KEY, d); refreshRecs(); refreshHist(); };
130	      const restore = keys => { const d = done(); keys.forEach(k => delete d[k]); save(OPT_KEY, d); refreshRecs(); refreshHist(); };
131	      const ruleEditor = r => SP.modal(r ? "Edit optimizer" : "Create optimizer", `
132	        <label class="field"><span>Optimizer name</span><input name="name" value="${r ? SP.esc(r.name) : ""}" placeholder="e.g. -25% bids if >= 50% ACOS"></label>
133	        <div class="detgrid"><label class="field"><span>When</span><select name="metric">${["ACOS", "Conversion", "Clicks", "Orders", "Spend", "Impressions"].map(m => `<option>${m}</option>`).join("")}</select></label><label class="field"><span>is at least</span><input name="val" type="number" value="60"></label></div>
134	        <label class="field"><span>Then</span><select name="sol">${["Adjust bid by -25%", "Adjust bid by -50%", "Adjust bid by +15%", "Move bid towards 30% ACOS", "Add keyword as negative exact", "Pause keyword"].map(s => `<option ${r && r.solution === s ? "selected" : ""}>${s}</option>`).join("")}</select></label>`, m => {
135	        const name = $("[name=name]", m).value.trim(); if (!name) return false;
136	        const metric = $("[name=metric]", m).value, val = $("[name=val]", m).value, sol = $("[name=sol]", m).value;
137	        const trigger = `${metric}: ≥ ${metric === "ACOS" || metric === "Conversion" ? (+val).toFixed(2) + "%" : metric === "Spend" ? "$" + (+val).toFixed(2) : val}`;
138	        const type = /negative/.test(sol) ? "Negation" : /Pause/.test(sol) ? "Status" : "Bidding";
139	        if (r) Object.assign(r, { name, trigger, solution: sol, type });
140	        else g.rules.rows.unshift({ _k: `u${Date.now()}`, name, trigger, solution: sol, type, hue: g.rules.rows.length % 10, active: true });
141	        saveRules(); SP.refreshGrid("rules"); SP.toast(r ? "Optimizer updated." : "Optimizer created.");
142	      }, r ? "Save" : "Create");
143	
144	      root.addEventListener("click", e => {
145	        const fix = e.target.closest("[data-fix]");
146	        if (fix) { mark(fix.dataset.fix, "fix"); SP.toast("Done (sample only): the change is listed under History."); }
147	        const ign = e.target.closest("[data-ignore]"); if (ign) { mark(ign.dataset.ignore, "ignore"); SP.toast("Recommendation ignored."); }
148	        const rs = e.target.closest("[data-restore]"); if (rs) { restore([rs.dataset.restore]); SP.toast("Change restored."); }
149	        if (e.target.closest("[data-revert]")) { restore(SP.gridChecked("hist")); SP.toast("Selected changes restored."); }
150	        if (e.target.closest("[data-hfilter]")) refreshHist();
151	        if (e.target.closest("[data-newrule]")) ruleEditor(null);
152	        const er = e.target.closest("[data-editrule]"); if (er) ruleEditor(g.rules.rows.find(x => x._k === er.dataset.editrule));
153	        const dr = e.target.closest("[data-delrule]");
154	        if (dr) SP.modal("Delete optimizer?", "<p>It stops making recommendations straight away.</p>", () => { g.rules.rows = g.rules.rows.filter(x => x._k !== dr.dataset.delrule); saveRules(); SP.refreshGrid("rules"); }, "Delete");
155	        const bulk = e.target.closest("[data-bulk]");
156	        if (bulk && !bulk.disabled) {
157	          e.stopPropagation();
158	          SP.popover(bulk, [{ label: "Turn on", on: true }, { label: "Turn off", on: false }, { label: "Delete", del: true }], it => {
159	            const sel = new Set(SP.gridChecked("rules"));
160	            if (it.del) g.rules.rows = g.rules.rows.filter(x => !sel.has(x._k)); else g.rules.rows.forEach(x => { if (sel.has(x._k)) x.active = it.on; });
161	            g.rules.checked.clear(); saveRules(); SP.refreshGrid("rules"); bulk.disabled = true;
162	          });
163	        }
164	      });
165	      root.addEventListener("change", e => {
166	        const a = e.target.closest("[data-active]");
167	        if (a) { const r = g.rules.rows.find(x => x._k === a.dataset.active); r.active = a.checked; saveRules(); SP.toast(`${r.name}: ${a.checked ? "on" : "off"}.`); }
168	        if (e.target.matches("[data-markets]")) SP.toast(e.target.checked ? "Showing all marketplaces." : "Showing the selected marketplace only.");
169	        // enable bulk buttons once something is ticked (after the shared handler updated the selection)
170	        setTimeout(() => { $("[data-bulk]", root).disabled = !g.rules.checked.size; $("[data-revert]", root).disabled = !g.hist.checked.size; });
171	      });
172	    },
173	  };
174	
175	  // ================= Ad group signals =================
176	  const SIGNALS = [
177	    ["Multi Target/Keyword AdGroup (SP)", "SP", 9, "Ad group with several targets in an SP campaign"],
178	    ["Multi Target/Keyword AdGroup (SB)", "SB", 9, "Ad group with several targets in an SB campaign"],
179	    ["No Placement Modifier", "SP", 9, "Ad group in an SP campaign without placement modifiers"],
180	    ["Bid Down Or Fixed", "SP", 9, "Ad group in a campaign using a down-only or fixed bid strategy"],
181	    ["Auto", "SP", 3, "Auto-targeting ad group in an SP campaign"],
182	    ["Keyword (SP)", "SP", 2, "Keyword-targeting ad group in an SP campaign"],
183	    ["Keyword (SB)", "SB", 2, "Keyword-targeting ad group in an SB campaign"],
184	    ["Not Exact (SP)", "SP", 2, "Ad group with no exact-match targets in an SP campaign"],
185	    ["Not Exact (SB)", "SB", 2, "Ad group with no exact-match targets in an SB campaign"],
186	    ["Product (SP)", "SP", 1, "Product-targeting ad group in an SP campaign"],
187	    ["Product (SB)", "SB", 1, "Product-targeting ad group in an SB campaign"],
188	  ].map(([name, type, used, desc], i) => ({ _k: `s${i}`, name, type, used, desc }));
189	  const SIG_KEY = "sp-signals";
190	  SP.pages["/AdGroupSignals"] = {
191	    title: "Ad group signals", noSub: true, section: "optimizer", icon: "signal", iconColor: "#6c757d",
192	    render() {
193	      return `${SP.note("Note: Ad group signals describe key traits of your ad groups, so the optimizer can make more accurate, better-targeted recommendations.")}
194	        <div class="actions tight"><button class="btn-soft" data-newsig>${svg(I.plus)}Create new</button><a class="btn-outline linkbtn" href="/ScaleOptimizer">Back to Optimizer</a></div>
195	        ${SP.grid({ id: "sig", agPager: true, pageSize: 20, columns: true, cls: "ag", sortKey: "used",
196	          cols: [
197	            { key: "_k", label: "Actions", sort: false, fmt: k => `<span class="rowacts"><button class="ic-round" data-editsig="${k}" aria-label="Edit">${svg(I.pencil)}</button><button class="ic-round" data-delsig="${k}" aria-label="Delete">${svg(I.trash)}</button></span>` },
198	            { key: "name", label: `Ad group signal <span class="ibox" title="A reusable description of ad group traits">i</span>`, w: 230, sort: false },
199	            { key: "type", label: "Ad type", filter: true, sort: false },
200	            { key: "used", label: "Used by optimizers", align: "r", filter: true },
201	            { key: "desc", label: "Description", filter: true, w: 420, sort: false },
202	          ],
203	          rows: load(SIG_KEY, null) || SIGNALS })}`;
204	    },
205	    wire(root) {
206	      const g = SP._grids.sig;
207	      const editor = s => {
208	        const previousFocus = document.activeElement;
209	        const m = document.createElement('div');
210	        m.className = 'modal-wrap signal-overlay';
211	        const check = (name, label, extra = '') => `<label class="signal-check"><input type="checkbox" name="${name}" checked>${label}${extra}</label>`;
212	        const info = '<span class="ibox" title="Filter ad groups by their targets">i</span>';
213	        const range = (name, label) => `<span class="signal-range"><input type="number" min="0" name="${name}Min" placeholder="At least" aria-label="${label} at least"><span>—</span><input type="number" min="0" name="${name}Max" placeholder="At most" aria-label="${label} at most"></span>`;
214	        const section = (name, title, body, type = '') => `<section class="signal-section" ${type}><h3>${check(name, title)}</h3><fieldset data-section="${name}">${body}</fieldset></section>`;
215	        const matches = ['Any single type', 'Exact only', 'Phrase only', 'Broad only', 'Exact', 'Phrase', 'Broad', 'Any but not Exact', 'Any but not Phrase', 'Any but not Broad', 'At least two types'];
216	        m.innerHTML = `<form class="signal-dialog" role="dialog" aria-modal="true" aria-labelledby="signal-title">
217	          <div class="signal-panel"><header><h2 id="signal-title">${s ? 'Edit' : 'Create'} ad group signal</h2></header><div class="signal-scroll">
218	          <section class="signal-section signal-types"><h3>Select applicable ad type:</h3>${['SP','SB','SD'].map(t => `<label><input type="radio" name="type" value="${t}" ${t === (s?.type || 'SP') ? 'checked' : ''}>${t}</label>`).join('')}</section>
219	          ${section('bidding', 'Campaign bidding strategies', `<p>Allowed bidding strategies:</p><div class="signal-strategies">${check('bidDown','Bid down')}${check('bidUpDown','Bid up and down')}${check('fixedBid','Fixed bid')}</div>`, 'data-sp')}
220	          ${section('placements', 'Campaign placement modifiers', `<label class="signal-check signal-no-modifiers"><input type="checkbox" name="noModifiers">Only campaigns without placement modifiers.</label><div data-placement-ranges>${[['top','Top of search'],['rest','Rest of search'],['pages','Product pages']].map(([key,label]) => `<div class="signal-row"><span>${label} (%):</span>${range(key,label)}</div>`).join('')}</div>`, 'data-sp')}
221	          ${section('targets', `Allowed ad groups targets ${info}`, `<div class="signal-row">${check('keywords','Keywords',info)}${range('keywords','Keywords')}</div><div class="signal-row">${check('products','Products',info)}${range('products','Products')}</div><div class="signal-row" data-sp>${check('auto','Auto targeting')}</div>`, 'data-search')}
222	          ${section('matchTypes', 'Keyword match types', `<div class="signal-match"><span>Ad group must have keyword with match type:</span><select name="match" aria-label="Keyword match type">${matches.map(t => `<option>${t}</option>`).join('')}</select></div>`, 'data-search')}
223	          <section class="signal-empty" data-display>No filters available for Sponsored Display ad group signals.</section>
224	          <section class="signal-section signal-color"><h3>Signal color</h3><details><summary aria-label="Signal color"><span class="signal-dot"></span><span class="caret"></span></summary><div class="signal-palette">${['#18c79a','#4796e0','#ab60da','#ed7676','#e8be42','#34445e'].map(c => `<button type="button" aria-label="Color ${c}" data-color="${c}" style="background:${c}"></button>`).join('')}</div></details><input type="hidden" name="color" value="#18c79a"></section>
225	          <details class="signal-section signal-description" open><summary>Description <span>⌃</span></summary><textarea name="desc" aria-label="Description" placeholder="Add context or notes for this ad group signal"></textarea></details>
226	          </div></div><footer class="signal-footer"><button type="button" data-cancel>Cancel</button><label>Name <span>*</span><input name="name" required placeholder="Enter name" autocomplete="off"></label><button type="submit" data-create disabled>${s ? 'Save' : 'Create'}</button></footer></form>`;
227	        const form = $('form', m);
228	        const field = name => form.elements.namedItem(name);
229	        field('name').value = s?.name || '';
230	        field('desc').value = s?.desc || '';
231	        if (s?.config) Object.entries(s.config).forEach(([name,value]) => {
232	          const el = field(name); if (!el) return;
233	          if (el.type === 'checkbox') el.checked = value; else el.value = value;
234	        });
235	        field('color').value = s?.color || '#18c79a';
236	        const update = () => {
237	          const type = field('type').value;
238	          $$('input,select',m).forEach(el => el.disabled = false);
239	          $$('[data-sp]',m).forEach(el => el.hidden = type !== 'SP');
240	          $$('[data-search]',m).forEach(el => el.hidden = type === 'SD');
241	          $('[data-display]',m).hidden = type !== 'SD';
242	          $$('[data-section]',m).forEach(el => el.disabled = !field(el.dataset.section).checked);
243	          $$('[data-placement-ranges] input',m).forEach(el => el.disabled = field('noModifiers').checked);
244	          ['keywords','products'].forEach(key => ['Min','Max'].forEach(suffix => field(key+suffix).disabled = !field(key).checked));
245	          $('[data-create]',m).disabled = !field('name').value.trim();
246	          $('.signal-dot',m).style.background = field('color').value;
247	          $$('[data-sp] input, [data-search] input, [data-search] select',m).forEach(el => { if (el.closest('[hidden]')) el.disabled = true; else if (!el.closest('fieldset') && el.type === 'checkbox') el.disabled = false; });
248	          $$('input[type=number]',m).forEach(el => el.setCustomValidity(''));
249	          ['top','rest','pages','keywords','products'].forEach(key => {
250	            const min = field(key+'Min'), max = field(key+'Max');
251	            if (!min.disabled && !max.disabled && min.value !== '' && max.value !== '' && +min.value > +max.value) max.setCustomValidity('At most must be greater than or equal to At least.');
252	          });
253	        };
254	        const oldOverflow = document.body.style.overflow;
255	        const close = () => { m.remove(); document.body.style.overflow = oldOverflow; previousFocus?.focus(); };
256	        m.addEventListener('click', e => {
257	          if (e.target === m || e.target.closest('[data-cancel]')) close();
258	          const color = e.target.closest('[data-color]');
259	          if (color) { field('color').value = color.dataset.color; color.closest('details').open = false; update(); }
260	        });
261	        m.addEventListener('input',update);
262	        m.addEventListener('change',update);
263	        m.addEventListener('keydown', e => {
264	          if (e.key === 'Escape') { e.preventDefault(); close(); }
265	          if (e.key === 'Tab') {
266	            const focusable = [...m.querySelectorAll('button,input,select,textarea,summary')].filter(el => !el.disabled && el.type !== 'hidden' && el.getClientRects().length);
267	            const first = focusable[0], last = focusable.at(-1);
268	            if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
269	            if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
270	          }
271	        });
272	        form.addEventListener('submit', e => {
273	          e.preventDefault(); update(); if (!form.reportValidity() || !field('name').value.trim()) return;
274	          const config = {};
275	          [...form.elements].filter(el => el.name && !['name','desc','type','color'].includes(el.name)).forEach(el => config[el.name] = el.type === 'checkbox' ? el.checked : el.value);
276	          const vals = { name: field('name').value.trim(), type: field('type').value, desc: field('desc').value.trim(), color: field('color').value, config };
277	          if (s) Object.assign(s, vals); else g.rows.push({ _k: `u${Date.now()}`, used: 0, ...vals });
278	          save(SIG_KEY,g.rows); SP.refreshGrid('sig'); close(); SP.toast(s ? 'Signal updated.' : 'Signal created.');
279	        });
280	        document.body.appendChild(m); document.body.style.overflow = 'hidden'; update(); $('input[name=type]:checked',m).focus();
281	      };
282	      root.addEventListener("click", e => {
283	        if (e.target.closest("[data-newsig]")) editor(null);
284	        const ed = e.target.closest("[data-editsig]"); if (ed) editor(g.rows.find(x => x._k === ed.dataset.editsig));
285	        const d = e.target.closest("[data-delsig]");
286	        if (d) {
287	          const s = g.rows.find(x => x._k === d.dataset.delsig);
288	          SP.modal("Delete signal?", s.used ? `<p>${s.used} optimizer${s.used > 1 ? "s use" : " uses"} this signal. They'll stop matching ad groups by it.</p>` : "<p>No optimizer uses this signal.</p>", () => { g.rows = g.rows.filter(x => x !== s); save(SIG_KEY, g.rows); SP.refreshGrid("sig"); }, "Delete");
289	        }
290	      });
291	    },
292	  };
293	})();
