/* Optimizer (recommendations, rules, history) and Ad group signals. */
(() => {
  "use strict";
  const SP = window.SP, { $, $$, svg, ICON: I } = SP;
  const P = SP.PRODUCTS;
  const load = (k, d) => { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } };
  const save = (k, v) => localStorage.setItem(k, JSON.stringify(v));
  SP.ICON.signal = '<circle cx="12" cy="12" r="9.5"/><path d="M14.8 9.2c-.6-.9-1.6-1.4-2.8-1.4-1.6 0-2.7.9-2.7 2.1 0 2.9 5.6 1.6 5.6 4.3 0 1.3-1.2 2.2-2.9 2.2-1.3 0-2.4-.6-2.9-1.5"/>';
  SP.ICON.optimizer = '<path d="M9 18h6M10 21h4M8 14c-4-5-1-12 4-12s8 7 4 12c-1 1-1 2-1 3H9c0-1 0-2-1-3Z"/><path d="m12 6-2 4h3l-2 4"/>';
  const swatch = h => `<span class="swatch2" style="--h:${SP.swatchColor(h)}"></span>`;
  const money2 = v => `$${v.toFixed(2)}`;
  const camp = (i, kind) => `${kind}-${["BROAD", "EXACT", "AUTO"][i % 3]}-RANK - ${P[i % 2].asin}`;
  const ag = i => `${P[i % 2].asin} - ${["Broad", "Exact", "Auto"][i % 3]}`;

  // ---------- Recommendations (sample) ----------
  const BID = [
    ["-33% bids if >= 60% ACOS", "training rope with handles", 67.33, null, 0.9, 0.6, 2],
    ["Default 30% ACOS keyword bid", "cordless battle rope", 45.74, 30, 0.6, 0.57, 3],
    ["Default 30% ACOS keyword bid", "training rope with handles", 31.94, 30, 1.2, 1.11, 3],
    ["Default 30% ACOS keyword bid", "weighted training rope", 26.69, 30, 0.9, 0.94, 3],
    ["Default 30% ACOS keyword bid", "jump rope for women", 21.34, 30, 0.65, 0.75, 3],
  ];
  const NEG_TERMS = ["fitness equipment", "fitness equipment", "fitness equipment", "fitness equipment", "home gym equipment", "home gym equipment", "home gym equipment", "home gym equipment", "fitness equipment", "fitness equipment", "battle ropes for exercise", "battle ropes for exercise", "weighted jump rope", "weighted jump rope", "weighted jump rope", "skipping rope", "skipping rope", "rope trainer", "exercise rope", "gym rope", "heavy rope"];
  const RECS = [
    ...BID.map(([opt, kw, acos, target, from, to, ri], i) => ({
      _k: `b${i}`, opt, hue: ri, market: "US", match: "Broad", kw, acos,
      solution: `${target ? `Target ACOS: <b>${target}%</b><br>` : ""}${to < from ? "Decrease" : "Increase"} bid: <b>${money2(from)} → ${money2(to)}</b>`,
      plain: `${to < from ? "Decrease" : "Increase"} bid ${money2(from)} → ${money2(to)}`, type: "Keyword", campaign: camp(i, "SP"), adgroup: ag(i),
    })),
    ...NEG_TERMS.map((kw, i) => ({
      _k: `n${i}`, opt: "Negate no-sale search terms [ASIN phrase/broad]", hue: 8, market: "US", match: "Exact", kw, acos: null,
      solution: "Add keyword as <b>negative exact</b>", plain: "Add keyword as negative exact", type: "Search term", campaign: camp(i + 1, "SP"), adgroup: ag(i + 1),
    })),
  ];

  // ---------- Rules (sample) ----------
  const RULES = [
    ["-60% bids if >= 100% ACOS", "ACOS: ≥ 100.00%", "Adjust bid by -60%", "Bidding", 0],
    ["-50% bids if >= 80% ACOS", "ACOS: ≥ 80.00%", "Adjust bid by -50%", "Bidding", 1],
    ["-33% bids if >= 60% ACOS", "ACOS: ≥ 60.00%", "Adjust bid by -33%", "Bidding", 2],
    ["Bad Conversions <=5%", "Conversion: 1.00% - 5.00%<br>Spend: ≥ $10.00", "Move bid towards 20% ACOS", "Bidding", 4],
    ["Bad Conversions <=5% (7 days)", "Conversion: 1.00% - 5.00%<br>Spend: ≥ $10.00", "Move bid towards 20% ACOS", "Bidding", 4],
    ["Good Conversions >= 20%", "Orders: ≥ 3<br>Conversion: ≥ 20.00%", "Move bid towards 40% ACOS", "Bidding", 5],
    ["Good Conversions >= 20% (7 days)", "Orders: ≥ 3<br>Conversion: ≥ 20.00%", "Move bid towards 40% ACOS", "Bidding", 5],
    ["Default 30% ACOS keyword bid", "Clicks: ≥ 10", "Move bid towards 30% ACOS", "Bidding", 3],
    ["Raise bids on strong converters", "Orders: ≥ 5<br>ACOS: ≤ 15.00%", "Adjust bid by +15%", "Bidding", 6],
    ["Negate no-sale search terms [ASIN phrase/broad]", "Clicks: ≥ 15<br>Orders: 0", "Add keyword as negative exact", "Negation", 8],
    ["Negate no-sale search terms [auto]", "Clicks: ≥ 20<br>Orders: 0", "Add keyword as negative exact", "Negation", 8],
    ["Pause keywords with no impressions", "Impressions: 0 (30 days)", "Pause keyword", "Status", 9],
  ].map(([name, trigger, solution, type, hue], i) => ({ _k: `r${i}`, name, trigger, solution, type, hue, active: true }));
  const HUES = ["#d9534f", "#e06a4e", "#e98a3f", "#3d7fe0", "#8b70cf", "#3aa57b", "#2e9bb5", "#c0407a", "#d9534f", "#6c757d"];
  SP.swatchColor = h => HUES[h % HUES.length];

  const OPT_KEY = "sp-opt-done", RULE_KEY = "sp-opt-rules";
  const done = () => load(OPT_KEY, {});
  const fmtTime = t => { const d = new Date(t); return `${SP.dash(d)} ${d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}`; };

  SP.pages["/ScaleOptimizer"] = {
    title: "Scale Optimizer", noSub: true, section: "optimizer", icon: "optimizer", iconColor: "#8b70cf",
    render() {
      const pending = RECS.filter(r => !done()[r._k]);
      const recGrid = SP.grid({
        id: "recs", agPager: true, pageSize: 20, columns: true, cls: "ag",
        toolsBefore: `<label class="switch green"><input type="checkbox" checked data-markets><span class="track"></span>All markets</label>`,
        cols: [
          { key: "_k", label: "Actions", sort: false, muted: false, fmt: k => `<span class="recacts"><button class="pill" data-fix="${k}">Fix once</button><button class="link-plain" data-ignore="${k}">Ignore</button></span>` },
          { key: "opt", label: "Optimiser", filter: true, w: 250, fmt: (v, r) => `<span class="optname">${swatch(r.hue)}<span>${SP.esc(v)}</span></span>` },
          { key: "market", label: "Marketplace", filter: true, sort: false },
          { key: "kw", label: "Target", filter: true, w: 200, fmt: (v, r) => `<span class="mbadge">${r.match}</span> ${SP.esc(v)}` },
          { key: "acos", label: "Current ACOS", filter: true, fmt: v => (v == null ? "" : `${v.toFixed(2)}%`) },
          { key: "solution", label: "Solution (Action to execute)", sort: false, w: 230, fmt: v => `<span class="sol">${v}</span>` },
          { key: "campaign", label: "Campaign Name", filter: true, w: 220 },
          { key: "adgroup", label: "Ad Group Name", filter: true, w: 170 },
        ],
        rows: pending, empty: "No recommendations right now. They refresh daily.",
      });
      const ruleGrid = SP.grid({
        id: "rules", agPager: true, pageSize: 20, columns: true, check: true, cls: "ag",
        toolsBefore: `<button class="btn-soft" data-newrule>${svg(I.plus)}Create new</button>`,
        tools: `<div class="anchor"><button class="plain-btn bulk" data-bulk disabled>Bulk edit ${SP.caret}</button></div>`,
        cols: [
          { key: "_k", label: "Actions", sort: false, fmt: k => `<span class="rowacts"><button class="ic-round" data-editrule="${k}" aria-label="Edit">${svg(I.pencil)}</button><button class="ic-round" data-delrule="${k}" aria-label="Delete">${svg(I.trash)}</button></span>` },
          { key: "active", label: "Active", filter: true, fmt: (v, r) => `<label class="switch green mini"><input type="checkbox" ${v ? "checked" : ""} data-active="${r._k}" aria-label="Active"><span class="track"></span></label>` },
          { key: "hue", label: "Color", sort: false, fmt: h => swatch(h) },
          { key: "name", label: "Optimizer name", filter: true, w: 230 },
          { key: "trigger", label: "Trigger condition", sort: false, w: 200, fmt: v => v },
          { key: "solution", label: "Solution (Action to execute)", filter: true, w: 230 },
          { key: "type", label: "Rule type", filter: true },
          { key: "ruleName", label: "Rule name", filter: true, w: 360, fmt: (_, r) => {
            const label = r.name.replace(' <=5%', '').replace(' >= 20%', '');
            const cut = r.solution.match(/Adjust bid by -(\d+)%/);
            const description = cut ? `Cut bids by ${cut[1]}% if ACOS >= ${r.trigger.replace(/[^0-9.]/g, '').replace('.00', '')}% and no adjustment in last 7 days` : /Bad Conversions/.test(r.name) ? `Adjust bids to 20% ACOS for ${/7 days/.test(r.name) ? 'recent ' : ''}bad ads with conversion <= 5% and spend >= $10` : /Good Conversions/.test(r.name) ? 'Move bids towards 40% ACOS for good ads with orders >= 3 and conversion >= 20%' : r.solution;
            return `<div class="optimizer-rule"><span class="rule-badge"><span aria-hidden="true">⚒</span>${SP.esc(label)}</span><small>${SP.esc(description)}</small></div>`;
          } },
        ],
        rows: load(RULE_KEY, null) || RULES,
      });
      const hist = SP.grid({
        id: "hist", agPager: true, pageSize: 10, columns: true, check: true, cls: "ag",
        toolsBefore: "", tools: `<button class="plain-btn bulk" data-revert disabled>Bulk revert</button>`,
        cols: [
          { key: "created", label: "Created", filter: true, fmt: v => fmtTime(v) },
          { key: "opt", label: "Optimizer Name", w: 200 },
          { key: "campaign", label: "Campaign Name", filter: true, w: 200 },
          { key: "adgroup", label: "Ad Group Name", filter: true, w: 150 },
          { key: "type", label: "Item Type", filter: true },
          { key: "kw", label: "Changed Item" },
          { key: "plain", label: "Performed Action", w: 200 },
          { key: "_k", label: "Restore", sort: false, fmt: k => `<button class="pill sm" data-restore="${k}">Restore</button>` },
        ],
        rows: [], empty: "No records found.",
      });
      const histPanel = `${SP.panel(`<div class="frow"><label class="ctl"><span>${svg(SP.ICON.calendar, "cal")}</span><input type="date" data-hfrom value="${SP.iso(SP.addDays(SP.today, -30))}" aria-label="Start date"> - <input type="date" data-hto value="${SP.iso(SP.today)}" aria-label="End date"></label><button class="btn-dark" data-hfilter>Filter</button></div>`)}${hist}`;
      return `<div class="actions tight"><a class="btn-outline linkbtn" href="/AdGroupSignals">Manage Signals</a></div>
        ${SP.tabs("opt", ["Recommendations", "Manage", "History"], 1, "ant")}${SP.panels("opt", [recGrid, ruleGrid, histPanel], 1)}`;
    },
    wire(root) {
      const g = SP._grids;
      const refreshRecs = () => { g.recs.rows = RECS.filter(r => !done()[r._k]); SP.refreshGrid("recs"); };
      const refreshHist = () => {
        const from = new Date(($("[data-hfrom]", root).value || "2000-01-01") + "T00:00:00").getTime();
        const to = new Date(($("[data-hto]", root).value || "2999-01-01") + "T23:59:59").getTime();
        const d = done();
        g.hist.rows = RECS.filter(r => d[r._k] && d[r._k].action === "fix" && d[r._k].t >= from && d[r._k].t <= to).map(r => ({ ...r, created: d[r._k].t }));
        g.hist.checked.clear(); SP.refreshGrid("hist"); $("[data-revert]", root).disabled = true;
      };
      const saveRules = () => save(RULE_KEY, g.rules.rows);
      refreshHist();
      const mark = (k, action) => { const d = done(); d[k] = { action, t: Date.now() }; save(OPT_KEY, d); refreshRecs(); refreshHist(); };
      const restore = keys => { const d = done(); keys.forEach(k => delete d[k]); save(OPT_KEY, d); refreshRecs(); refreshHist(); };
      const ruleEditor = r => SP.modal(r ? "Edit optimizer" : "Create optimizer", `
        <label class="field"><span>Optimizer name</span><input name="name" value="${r ? SP.esc(r.name) : ""}" placeholder="e.g. -25% bids if >= 50% ACOS"></label>
        <div class="detgrid"><label class="field"><span>When</span><select name="metric">${["ACOS", "Conversion", "Clicks", "Orders", "Spend", "Impressions"].map(m => `<option>${m}</option>`).join("")}</select></label><label class="field"><span>is at least</span><input name="val" type="number" value="60"></label></div>
        <label class="field"><span>Then</span><select name="sol">${["Adjust bid by -25%", "Adjust bid by -50%", "Adjust bid by +15%", "Move bid towards 30% ACOS", "Add keyword as negative exact", "Pause keyword"].map(s => `<option ${r && r.solution === s ? "selected" : ""}>${s}</option>`).join("")}</select></label>`, m => {
        const name = $("[name=name]", m).value.trim(); if (!name) return false;
        const metric = $("[name=metric]", m).value, val = $("[name=val]", m).value, sol = $("[name=sol]", m).value;
        const trigger = `${metric}: ≥ ${metric === "ACOS" || metric === "Conversion" ? (+val).toFixed(2) + "%" : metric === "Spend" ? "$" + (+val).toFixed(2) : val}`;
        const type = /negative/.test(sol) ? "Negation" : /Pause/.test(sol) ? "Status" : "Bidding";
        if (r) Object.assign(r, { name, trigger, solution: sol, type });
        else g.rules.rows.unshift({ _k: `u${Date.now()}`, name, trigger, solution: sol, type, hue: g.rules.rows.length % 10, active: true });
        saveRules(); SP.refreshGrid("rules"); SP.toast(r ? "Optimizer updated." : "Optimizer created.");
      }, r ? "Save" : "Create");

      root.addEventListener("click", e => {
        const fix = e.target.closest("[data-fix]");
        if (fix) { mark(fix.dataset.fix, "fix"); SP.toast("Done (sample only): the change is listed under History."); }
        const ign = e.target.closest("[data-ignore]"); if (ign) { mark(ign.dataset.ignore, "ignore"); SP.toast("Recommendation ignored."); }
        const rs = e.target.closest("[data-restore]"); if (rs) { restore([rs.dataset.restore]); SP.toast("Change restored."); }
        if (e.target.closest("[data-revert]")) { restore(SP.gridChecked("hist")); SP.toast("Selected changes restored."); }
        if (e.target.closest("[data-hfilter]")) refreshHist();
        if (e.target.closest("[data-newrule]")) ruleEditor(null);
        const er = e.target.closest("[data-editrule]"); if (er) ruleEditor(g.rules.rows.find(x => x._k === er.dataset.editrule));
        const dr = e.target.closest("[data-delrule]");
        if (dr) SP.modal("Delete optimizer?", "<p>It stops making recommendations straight away.</p>", () => { g.rules.rows = g.rules.rows.filter(x => x._k !== dr.dataset.delrule); saveRules(); SP.refreshGrid("rules"); }, "Delete");
        const bulk = e.target.closest("[data-bulk]");
        if (bulk && !bulk.disabled) {
          e.stopPropagation();
          SP.popover(bulk, [{ label: "Turn on", on: true }, { label: "Turn off", on: false }, { label: "Delete", del: true }], it => {
            const sel = new Set(SP.gridChecked("rules"));
            if (it.del) g.rules.rows = g.rules.rows.filter(x => !sel.has(x._k)); else g.rules.rows.forEach(x => { if (sel.has(x._k)) x.active = it.on; });
            g.rules.checked.clear(); saveRules(); SP.refreshGrid("rules"); bulk.disabled = true;
          });
        }
      });
      root.addEventListener("change", e => {
        const a = e.target.closest("[data-active]");
        if (a) { const r = g.rules.rows.find(x => x._k === a.dataset.active); r.active = a.checked; saveRules(); SP.toast(`${r.name}: ${a.checked ? "on" : "off"}.`); }
        if (e.target.matches("[data-markets]")) SP.toast(e.target.checked ? "Showing all marketplaces." : "Showing the selected marketplace only.");
        // enable bulk buttons once something is ticked (after the shared handler updated the selection)
        setTimeout(() => { $("[data-bulk]", root).disabled = !g.rules.checked.size; $("[data-revert]", root).disabled = !g.hist.checked.size; });
      });
    },
  };

  // ================= Ad group signals =================
  const SIGNALS = [
    ["Multi Target/Keyword AdGroup (SP)", "SP", 9, "Ad group with several targets in an SP campaign"],
    ["Multi Target/Keyword AdGroup (SB)", "SB", 9, "Ad group with several targets in an SB campaign"],
    ["No Placement Modifier", "SP", 9, "Ad group in an SP campaign without placement modifiers"],
    ["Bid Down Or Fixed", "SP", 9, "Ad group in a campaign using a down-only or fixed bid strategy"],
    ["Auto", "SP", 3, "Auto-targeting ad group in an SP campaign"],
    ["Keyword (SP)", "SP", 2, "Keyword-targeting ad group in an SP campaign"],
    ["Keyword (SB)", "SB", 2, "Keyword-targeting ad group in an SB campaign"],
    ["Not Exact (SP)", "SP", 2, "Ad group with no exact-match targets in an SP campaign"],
    ["Not Exact (SB)", "SB", 2, "Ad group with no exact-match targets in an SB campaign"],
    ["Product (SP)", "SP", 1, "Product-targeting ad group in an SP campaign"],
    ["Product (SB)", "SB", 1, "Product-targeting ad group in an SB campaign"],
  ].map(([name, type, used, desc], i) => ({ _k: `s${i}`, name, type, used, desc }));
  const SIG_KEY = "sp-signals";
  SP.pages["/AdGroupSignals"] = {
    title: "Ad group signals", noSub: true, section: "optimizer", icon: "signal", iconColor: "#6c757d",
    render() {
      return `${SP.note("Note: Ad group signals describe key traits of your ad groups, so the optimizer can make more accurate, better-targeted recommendations.")}
        <div class="actions tight"><button class="btn-soft" data-newsig>${svg(I.plus)}Create new</button><a class="btn-outline linkbtn" href="/ScaleOptimizer">Back to Optimizer</a></div>
        ${SP.grid({ id: "sig", agPager: true, pageSize: 20, columns: true, cls: "ag", sortKey: "used",
          cols: [
            { key: "_k", label: "Actions", sort: false, fmt: k => `<span class="rowacts"><button class="ic-round" data-editsig="${k}" aria-label="Edit">${svg(I.pencil)}</button><button class="ic-round" data-delsig="${k}" aria-label="Delete">${svg(I.trash)}</button></span>` },
            { key: "name", label: `Ad group signal <span class="ibox" title="A reusable description of ad group traits">i</span>`, w: 230, sort: false },
            { key: "type", label: "Ad type", filter: true, sort: false },
            { key: "used", label: "Used by optimizers", align: "r", filter: true },
            { key: "desc", label: "Description", filter: true, w: 420, sort: false },
          ],
          rows: load(SIG_KEY, null) || SIGNALS })}`;
    },
    wire(root) {
      const g = SP._grids.sig;
      const editor = s => {
        const previousFocus = document.activeElement;
        const m = document.createElement('div');
        m.className = 'modal-wrap signal-overlay';
        const check = (name, label, extra = '') => `<label class="signal-check"><input type="checkbox" name="${name}" checked>${label}${extra}</label>`;
        const info = '<span class="ibox" title="Filter ad groups by their targets">i</span>';
        const range = (name, label) => `<span class="signal-range"><input type="number" min="0" name="${name}Min" placeholder="At least" aria-label="${label} at least"><span>—</span><input type="number" min="0" name="${name}Max" placeholder="At most" aria-label="${label} at most"></span>`;
        const section = (name, title, body, type = '') => `<section class="signal-section" ${type}><h3>${check(name, title)}</h3><fieldset data-section="${name}">${body}</fieldset></section>`;
        const matches = ['Any single type', 'Exact only', 'Phrase only', 'Broad only', 'Exact', 'Phrase', 'Broad', 'Any but not Exact', 'Any but not Phrase', 'Any but not Broad', 'At least two types'];
        m.innerHTML = `<form class="signal-dialog" role="dialog" aria-modal="true" aria-labelledby="signal-title">
          <div class="signal-panel"><header><h2 id="signal-title">${s ? 'Edit' : 'Create'} ad group signal</h2></header><div class="signal-scroll">
          <section class="signal-section signal-types"><h3>Select applicable ad type:</h3>${['SP','SB','SD'].map(t => `<label><input type="radio" name="type" value="${t}" ${t === (s?.type || 'SP') ? 'checked' : ''}>${t}</label>`).join('')}</section>
          ${section('bidding', 'Campaign bidding strategies', `<p>Allowed bidding strategies:</p><div class="signal-strategies">${check('bidDown','Bid down')}${check('bidUpDown','Bid up and down')}${check('fixedBid','Fixed bid')}</div>`, 'data-sp')}
          ${section('placements', 'Campaign placement modifiers', `<label class="signal-check signal-no-modifiers"><input type="checkbox" name="noModifiers">Only campaigns without placement modifiers.</label><div data-placement-ranges>${[['top','Top of search'],['rest','Rest of search'],['pages','Product pages']].map(([key,label]) => `<div class="signal-row"><span>${label} (%):</span>${range(key,label)}</div>`).join('')}</div>`, 'data-sp')}
          ${section('targets', `Allowed ad groups targets ${info}`, `<div class="signal-row">${check('keywords','Keywords',info)}${range('keywords','Keywords')}</div><div class="signal-row">${check('products','Products',info)}${range('products','Products')}</div><div class="signal-row" data-sp>${check('auto','Auto targeting')}</div>`, 'data-search')}
          ${section('matchTypes', 'Keyword match types', `<div class="signal-match"><span>Ad group must have keyword with match type:</span><select name="match" aria-label="Keyword match type">${matches.map(t => `<option>${t}</option>`).join('')}</select></div>`, 'data-search')}
          <section class="signal-empty" data-display>No filters available for Sponsored Display ad group signals.</section>
          <section class="signal-section signal-color"><h3>Signal color</h3><details><summary aria-label="Signal color"><span class="signal-dot"></span><span class="caret"></span></summary><div class="signal-palette">${['#18c79a','#4796e0','#ab60da','#ed7676','#e8be42','#34445e'].map(c => `<button type="button" aria-label="Color ${c}" data-color="${c}" style="background:${c}"></button>`).join('')}</div></details><input type="hidden" name="color" value="#18c79a"></section>
          <details class="signal-section signal-description" open><summary>Description <span>⌃</span></summary><textarea name="desc" aria-label="Description" placeholder="Add context or notes for this ad group signal"></textarea></details>
          </div></div><footer class="signal-footer"><button type="button" data-cancel>Cancel</button><label>Name <span>*</span><input name="name" required placeholder="Enter name" autocomplete="off"></label><button type="submit" data-create disabled>${s ? 'Save' : 'Create'}</button></footer></form>`;
        const form = $('form', m);
        const field = name => form.elements.namedItem(name);
        field('name').value = s?.name || '';
        field('desc').value = s?.desc || '';
        if (s?.config) Object.entries(s.config).forEach(([name,value]) => {
          const el = field(name); if (!el) return;
          if (el.type === 'checkbox') el.checked = value; else el.value = value;
        });
        field('color').value = s?.color || '#18c79a';
        const update = () => {
          const type = field('type').value;
          $$('input,select',m).forEach(el => el.disabled = false);
          $$('[data-sp]',m).forEach(el => el.hidden = type !== 'SP');
          $$('[data-search]',m).forEach(el => el.hidden = type === 'SD');
          $('[data-display]',m).hidden = type !== 'SD';
          $$('[data-section]',m).forEach(el => el.disabled = !field(el.dataset.section).checked);
          $$('[data-placement-ranges] input',m).forEach(el => el.disabled = field('noModifiers').checked);
          ['keywords','products'].forEach(key => ['Min','Max'].forEach(suffix => field(key+suffix).disabled = !field(key).checked));
          $('[data-create]',m).disabled = !field('name').value.trim();
          $('.signal-dot',m).style.background = field('color').value;
          $$('[data-sp] input, [data-search] input, [data-search] select',m).forEach(el => { if (el.closest('[hidden]')) el.disabled = true; else if (!el.closest('fieldset') && el.type === 'checkbox') el.disabled = false; });
          $$('input[type=number]',m).forEach(el => el.setCustomValidity(''));
          ['top','rest','pages','keywords','products'].forEach(key => {
            const min = field(key+'Min'), max = field(key+'Max');
            if (!min.disabled && !max.disabled && min.value !== '' && max.value !== '' && +min.value > +max.value) max.setCustomValidity('At most must be greater than or equal to At least.');
          });
        };
        const oldOverflow = document.body.style.overflow;
        const close = () => { m.remove(); document.body.style.overflow = oldOverflow; previousFocus?.focus(); };
        m.addEventListener('click', e => {
          if (e.target === m || e.target.closest('[data-cancel]')) close();
          const color = e.target.closest('[data-color]');
          if (color) { field('color').value = color.dataset.color; color.closest('details').open = false; update(); }
        });
        m.addEventListener('input',update);
        m.addEventListener('change',update);
        m.addEventListener('keydown', e => {
          if (e.key === 'Escape') { e.preventDefault(); close(); }
          if (e.key === 'Tab') {
            const focusable = [...m.querySelectorAll('button,input,select,textarea,summary')].filter(el => !el.disabled && el.type !== 'hidden' && el.getClientRects().length);
            const first = focusable[0], last = focusable.at(-1);
            if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
            if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
          }
        });
        form.addEventListener('submit', e => {
          e.preventDefault(); update(); if (!form.reportValidity() || !field('name').value.trim()) return;
          const config = {};
          [...form.elements].filter(el => el.name && !['name','desc','type','color'].includes(el.name)).forEach(el => config[el.name] = el.type === 'checkbox' ? el.checked : el.value);
          const vals = { name: field('name').value.trim(), type: field('type').value, desc: field('desc').value.trim(), color: field('color').value, config };
          if (s) Object.assign(s, vals); else g.rows.push({ _k: `u${Date.now()}`, used: 0, ...vals });
          save(SIG_KEY,g.rows); SP.refreshGrid('sig'); close(); SP.toast(s ? 'Signal updated.' : 'Signal created.');
        });
        document.body.appendChild(m); document.body.style.overflow = 'hidden'; update(); $('input[name=type]:checked',m).focus();
      };
      root.addEventListener("click", e => {
        if (e.target.closest("[data-newsig]")) editor(null);
        const ed = e.target.closest("[data-editsig]"); if (ed) editor(g.rows.find(x => x._k === ed.dataset.editsig));
        const d = e.target.closest("[data-delsig]");
        if (d) {
          const s = g.rows.find(x => x._k === d.dataset.delsig);
          SP.modal("Delete signal?", s.used ? `<p>${s.used} optimizer${s.used > 1 ? "s use" : " uses"} this signal. They'll stop matching ad groups by it.</p>` : "<p>No optimizer uses this signal.</p>", () => { g.rows = g.rows.filter(x => x !== s); save(SIG_KEY, g.rows); SP.refreshGrid("sig"); }, "Delete");
        }
      });
    },
  };
})();

