.signal-panel { background:#fff; border-radius:14px; overflow:hidden; display:flex; flex-direction:column; min-height:0; }
.signal-panel header { padding:20px 24px; border-bottom:1px solid #dce0e4; flex-shrink:0; }
.signal-panel h2,.signal-dialog h3 { font-size:20px; font-weight:500; margin:0; }
.signal-scroll { overflow:auto; overscroll-behavior:contain; }
.signal-section { padding:28px 24px; border-bottom:1px solid #dce0e4; }
.signal-dialog [hidden] { display:none!important; }
.signal-types { display:flex; align-items:center; gap:44px; }
.signal-types h3 { margin-right:-20px; }
.signal-types label,.signal-check { display:inline-flex; align-items:center; gap:8px; }
.signal-dialog input[type=checkbox],.signal-dialog input[type=radio] { width:16px; height:16px; margin:0; accent-color:#374862; flex-shrink:0; }
.signal-dialog fieldset { border:0; padding:0 0 0 24px; margin:30px 0 0; min-width:0; }
.signal-dialog fieldset:disabled { opacity:.5; }
.signal-dialog fieldset p { margin:0 0 24px; }
.signal-strategies { display:flex; gap:30px; }
.signal-no-modifiers { margin:0 0 30px; }
.signal-row { display:flex; align-items:center; justify-content:space-between; gap:16px; min-height:40px; margin-top:16px; }
.signal-row:first-child { margin-top:0; }
.signal-range { display:flex; align-items:center; gap:5px; }
.signal-dialog input:not([type=radio]):not([type=checkbox]):not([type=hidden]),.signal-dialog select,.signal-dialog textarea { font:inherit; color:inherit; background:#fff; border:1px solid #cfd6de; border-radius:14px; padding:10px 12px; min-width:0; }
.signal-dialog input::placeholder,.signal-dialog textarea::placeholder { color:#bfc1c3; opacity:1; }
.signal-range input { width:116px; text-align:center; appearance:textfield; }
.signal-range input::-webkit-inner-spin-button { appearance:none; }
.signal-dialog input:disabled { background:#f4f5f6!important; }
.signal-match { display:flex; align-items:center; gap:10px; }
.signal-match select { width:200px; }
.signal-color { display:flex; align-items:center; gap:12px; padding-top:24px; padding-bottom:24px; }
.signal-color details { position:relative; }
.signal-color summary { display:flex; align-items:center; gap:18px; padding:12px; border:1px solid #cfd6de; border-radius:14px; cursor:pointer; list-style:none; }
.signal-dot { width:16px; height:16px; border-radius:50%; }
.signal-palette { position:absolute; z-index:2; top:100%; display:flex; gap:8px; background:white; padding:12px; border-radius:12px; box-shadow:0 4px 20px #0003; }
.signal-palette button { width:24px; height:24px; border:0; border-radius:50%; cursor:pointer; }
.signal-description summary { list-style:none; display:flex; justify-content:space-between; font-size:20px; cursor:pointer; }
.signal-description:not([open]) summary span { transform:rotate(180deg); }
.signal-description textarea { display:block; width:100%; height:110px; resize:vertical; margin-top:36px; }
.signal-empty { padding:100px 24px; text-align:center; color:#7b858e; }
.signal-footer { flex-shrink:0; margin-top:5px; background:#f7f8f9; border-radius:14px 14px 0 0; padding:24px; display:flex; align-items:center; gap:24px; }
.signal-footer button { height:40px; flex:0 0 180px; border:1px solid #cfd6de; border-radius:14px; font:inherit; cursor:pointer; background:#e4e7eb; color:inherit; }
.signal-footer label { display:flex; align-items:center; gap:6px; flex:1; white-space:nowrap; }
.signal-footer label span { color:#dc3545; }
.signal-footer input { width:100%; margin-left:4px; height:40px; }
.signal-footer button[type=submit] { background:#374862; color:white; }
.signal-footer button:disabled { background:#c3c7cd; border-color:#c3c7cd; cursor:default; }
@media(max-width:700px) { .signal-overlay { padding:12px 10px 0; }.signal-dialog{max-height:calc(100dvh - 12px);font-size:14px}.signal-section{padding:20px 16px}.signal-types{gap:20px;flex-wrap:wrap}.signal-types h3{width:100%}.signal-dialog h3,.signal-panel h2{font-size:18px}.signal-dialog fieldset{padding-left:8px}.signal-strategies{flex-wrap:wrap;gap:16px}.signal-match{flex-wrap:wrap}.signal-row{flex-wrap:wrap}.signal-footer{padding:16px;gap:12px;flex-wrap:wrap}.signal-footer label{order:-1;flex-basis:100%}.signal-footer button{flex:1}.signal-range input{width:90px} }

/* Scale Optimizer layout from the supplied Manage screenshots. */
body:has([data-tabs="opt"]) { font-family:Arial,sans-serif; }
body:has([data-tabs="opt"]) .page-title { color:#50575e; }
body:has([data-tabs="opt"]) .rail-item.active { background:transparent; }
.page-optimizer:has([data-tabs="opt"]) .actions.tight { margin:8px 8px 30px; }
.page-optimizer:has([data-tabs="opt"]) .linkbtn { height:38px; border-radius:14px; font-size:16px; color:#292d31; box-shadow:0 1px 2px #0001; }
.page-optimizer [data-tabs="opt"] { width:max-content; max-width:100%; gap:16px; margin:0 0 24px; border-bottom:1px solid #aeb5bd; }
.page-optimizer [data-tabs="opt"] button { padding:10px 0 14px; color:#292d31; font-size:16px; }
.page-optimizer [data-tabs="opt"] button.on { border-bottom-color:#30363a; }
.page-optimizer [data-panels="opt"] .grid-tools { margin:0 0 24px; gap:16px; }
.page-optimizer [data-panels="opt"] .instant { width:200px; height:38px; border-radius:14px; }
.page-optimizer [data-panels="opt"] .instant input { font-size:16px; }
.page-optimizer [data-panels="opt"] .instant input::placeholder { color:#bcbfc2; }
.page-optimizer [data-panels="opt"] .btn-soft { display:inline-flex; align-items:center; gap:8px; height:38px; padding:0 14px; border:0; border-radius:14px; background:#f0e6ff; color:#9763d4; font-size:16px; font-weight:600; cursor:pointer; }
.page-optimizer [data-panels="opt"] .btn-soft svg { width:16px; height:16px; }
.page-optimizer [data-panel="1"] .grid-tools > .anchor:has([data-bulk]) { order:2; padding:0 24px 0 12px; border-right:1px solid #dce0e5; }
.page-optimizer [data-panel="1"] .grid-tools > .anchor:has([data-gcols]) { order:3; }
.page-optimizer [data-panels="opt"] [data-gcols] { height:38px; padding:0 14px; border:1px solid #d5d8dc; border-radius:14px; font-size:16px; box-shadow:0 1px 2px #0001; }
.page-optimizer [data-panels="opt"] [data-gcols] svg { width:20px; height:20px; }
.page-optimizer [data-panels="opt"] .bulk { height:36px; font-size:16px; gap:14px; }
.page-optimizer [data-panels="opt"] .bulk:disabled { color:#c4cbd3; }
.page-optimizer [data-panels="opt"] .grid-wrap { max-width:calc(100% + 20px); margin-left:-20px; margin-right:0; }
.page-optimizer [data-grid="rules"] { table-layout:fixed; width:1898px; font-size:16px; }
.page-optimizer [data-grid="rules"] th { height:54px; padding:16px 18px; border-left:0; vertical-align:middle; overflow:hidden; text-overflow:ellipsis; }
.page-optimizer [data-grid="rules"] th::after { content:'⋮'; position:absolute; right:10px; top:18px; color:#d3dce5; border-right:2px solid #e9ecef; padding-right:16px; }
.page-optimizer [data-grid="rules"] th:first-child::after { display:none; }
.page-optimizer [data-grid="rules"] th:nth-child(1) { width:48px; }
.page-optimizer [data-grid="rules"] th:nth-child(2) { width:110px; }
.page-optimizer [data-grid="rules"] th:nth-child(3) { width:115px; }
.page-optimizer [data-grid="rules"] th:nth-child(4) { width:95px; }
.page-optimizer [data-grid="rules"] th:nth-child(5) { width:290px; }
.page-optimizer [data-grid="rules"] th:nth-child(6) { width:300px; }
.page-optimizer [data-grid="rules"] th:nth-child(7) { width:340px; }
.page-optimizer [data-grid="rules"] th:nth-child(8) { width:140px; }
.page-optimizer [data-grid="rules"] th:nth-child(9) { width:360px; }
.page-optimizer [data-grid="rules"] .th-tools { display:inline-flex; margin:0 22px 0 8px; float:right; }
.page-optimizer [data-grid="rules"] .arr:not(.on) { display:none; }
.page-optimizer [data-grid="rules"] td { height:108px; padding:18px 16px; white-space:normal; line-height:1.4; }
.page-optimizer [data-grid="rules"] tbody tr:hover { background:#f1f3f4; }
.page-optimizer [data-grid="rules"] input[type="checkbox"]:not(.switch input) { width:16px; height:16px; accent-color:#5cac98; }
.page-optimizer [data-grid="rules"] .rowacts { display:flex; gap:4px; }
.page-optimizer [data-grid="rules"] .ic-round { width:38px; height:38px; border:1px solid #e4e8ec; border-radius:14px; background:white; color:#7b858d; display:grid; place-items:center; cursor:pointer; box-shadow:0 1px 2px #0001; }
.page-optimizer [data-grid="rules"] .ic-round svg { width:20px; height:20px; }
.page-optimizer [data-grid="rules"] .swatch2 { width:22px; height:22px; border-radius:4px; background:linear-gradient(90deg,#d9686c 50%,#fff0d5 50%); }
.page-optimizer [data-grid="rules"] .track { width:28px; height:16px; background:#c9ced6; }
.page-optimizer [data-grid="rules"] .track::after { width:12px; height:12px; top:2px; left:2px; }
.page-optimizer [data-grid="rules"] input:checked + .track { background:#5cac98; }
.page-optimizer [data-grid="rules"] input:checked + .track::after { left:14px; }
.optimizer-rule .rule-badge { display:inline-flex; align-items:center; gap:5px; border:1px solid #cdd5dc; border-radius:20px; padding:3px 10px; white-space:nowrap; }
.optimizer-rule .rule-badge > span { color:#63b6b4; }
.optimizer-rule small { display:block; font-size:12px; line-height:1.2; margin-top:8px; }
@media(max-width:767px) { .page-optimizer:has([data-tabs="opt"]) .actions.tight { margin-top:24px; }.page-optimizer [data-panels="opt"] .grid-wrap { margin-left:0; max-width:100%; } }

content.content:
1	/* Optimizer (recommendations, rules, history) and Ad group signals. */
2	(() => {
3	  "use strict";
4	  const SP = window.SP, { $, $$, svg, ICON: I } = SP;
5	  const P = SP.PRODUCTS;
6	  const load = (k, d) => { try { return JSON.parse(localStorage.getItem(k)) ?? d; } catch { return d; } };
7	  const save = (k, v) => localStorage.setItem(k, JSON.stringify(v));
8	  SP.ICON.signal = '<circle cx="12" cy="12" r="9.5"/><path d="M14.8 9.2c-.6-.9-1.6-1.4-2.8-1.4-1.6 0-2.7.9-2.7 2.1 0 2.9 5.6 1.6 5.6 4.3 0 1.3-1.2 2.2-2.9 2.2-1.3 0-2.4-.6-2.9-1.5"/>';
9	  SP.ICON.optimizer = '<path d="M9 18h6M10 21h4M8 14c-4-5-1-12 4-12s8 7 4 12c-1 1-1 2-1 3H9c0-1 0-2-1-3Z"/><path d="m12 6-2 4h3l-2 4"/>';
10	  const swatch = h => `<span class="swatch2" style="--h:${SP.swatchColor(h)}"></span>`;
11	  const money2 = v => `$${v.toFixed(2)}`;
12	  const camp = (i, kind) => `${kind}-${["BROAD", "EXACT", "AUTO"][i % 3]}-RANK - ${P[i % 2].asin}`;
13	  const ag = i => `${P[i % 2].asin} - ${["Broad", "Exact", "Auto"][i % 3]}`;
14	
15	  // ---------- Recommendations (sample) ----------
16	  const BID = [
17	    ["-33% bids if >= 60% ACOS", "training rope with handles", 67.33, null, 0.9, 0.6, 2],
18	    ["Default 30% ACOS keyword bid", "cordless battle rope", 45.74, 30, 0.6, 0.57, 3],
19	    ["Default 30% ACOS keyword bid", "training rope with handles", 31.94, 30, 1.2, 1.11, 3],
20	    ["Default 30% ACOS keyword bid", "weighted training rope", 26.69, 30, 0.9, 0.94, 3],
21	    ["Default 30% ACOS keyword bid", "jump rope for women", 21.34, 30, 0.65, 0.75, 3],
22	  ];
23	  const NEG_TERMS = ["fitness equipment", "fitness equipment", "fitness equipment", "fitness equipment", "home gym equipment", "home gym equipment", "home gym equipment", "home gym equipment", "fitness equipment", "fitness equipment", "battle ropes for exercise", "battle ropes for exercise", "weighted jump rope", "weighted jump rope", "weighted jump rope", "skipping rope", "skipping rope", "rope trainer", "exercise rope", "gym rope", "heavy rope"];
24	  const RECS = [
25	    ...BID.map(([opt, kw, acos, target, from, to, ri], i) => ({
26	      _k: `b${i}`, opt, hue: ri, market: "US", match: "Broad", kw, acos,
27	      solution: `${target ? `Target ACOS: <b>${target}%</b><br>` : ""}${to < from ? "Decrease" : "Increase"} bid: <b>${money2(from)} → ${money2(to)}</b>`,
28	      plain: `${to < from ? "Decrease" : "Increase"} bid ${money2(from)} → ${money2(to)}`, type: "Keyword", campaign: camp(i, "SP"), adgroup: ag(i),
29	    })),
30	    ...NEG_TERMS.map((kw, i) => ({
31	      _k: `n${i}`, opt: "Negate no-sale search terms [ASIN phrase/broad]", hue: 8, market: "US", match: "Exact", kw, acos: null,
32	      solution: "Add keyword as <b>negative exact</b>", plain: "Add keyword as negative exact", type: "Search term", campaign: camp(i + 1, "SP"), adgroup: ag(i + 1),
33	    })),
34	  ];
35	
36	  // ---------- Rules (sample) ----------
37	  const RULES = [
38	    ["-60% bids if >= 100% ACOS", "ACOS: ≥ 100.00%", "Adjust bid by -60%", "Bidding", 0],
39	    ["-50% bids if >= 80% ACOS", "ACOS: ≥ 80.00%", "Adjust bid by -50%", "Bidding", 1],
40	    ["-33% bids if >= 60% ACOS", "ACOS: ≥ 60.00%", "Adjust bid by -33%", "Bidding", 2],
41	    ["Bad Conversions <=5%", "Conversion: 1.00% - 5.00%<br>Spend: ≥ $10.00", "Move bid towards 20% ACOS", "Bidding", 4],
42	    ["Bad Conversions <=5% (7 days)", "Conversion: 1.00% - 5.00%<br>Spend: ≥ $10.00", "Move bid towards 20% ACOS", "Bidding", 4],
43	    ["Good Conversions >= 20%", "Orders: ≥ 3<br>Conversion: ≥ 20.00%", "Move bid towards 40% ACOS", "Bidding", 5],
44	    ["Good Conversions >= 20% (7 days)", "Orders: ≥ 3<br>Conversion: ≥ 20.00%", "Move bid towards 40% ACOS", "Bidding", 5],
45	    ["Default 30% ACOS keyword bid", "Clicks: ≥ 10", "Move bid towards 30% ACOS", "Bidding", 3],
46	    ["Raise bids on strong converters", "Orders: ≥ 5<br>ACOS: ≤ 15.00%", "Adjust bid by +15%", "Bidding", 6],
47	    ["Negate no-sale search terms [ASIN phrase/broad]", "Clicks: ≥ 15<br>Orders: 0", "Add keyword as negative exact", "Negation", 8],
48	    ["Negate no-sale search terms [auto]", "Clicks: ≥ 20<br>Orders: 0", "Add keyword as negative exact", "Negation", 8],
49	    ["Pause keywords with no impressions", "Impressions: 0 (30 days)", "Pause keyword", "Status", 9],
50	  ].map(([name, trigger, solution, type, hue], i) => ({ _k: `r${i}`, name, trigger, solution, type, hue, active: true }));
51	  const HUES = ["#d9534f", "#e06a4e", "#e98a3f", "#3d7fe0", "#8b70cf", "#3aa57b", "#2e9bb5", "#c0407a", "#d9534f", "#6c757d"];
52	  SP.swatchColor = h => HUES[h % HUES.length];
53	
54	  const OPT_KEY = "sp-opt-done", RULE_KEY = "sp-opt-rules";
55	  const done = () => load(OPT_KEY, {});
56	  const fmtTime = t => { const d = new Date(t); return `${SP.dash(d)} ${d.toLocaleTimeString("en-US", { hour: "numeric", minute: "2-digit" })}`; };
57	
58	  SP.pages["/ScaleOptimizer"] = {
59	    title: "Scale Optimizer", noSub: true, section: "optimizer", icon: "optimizer", iconColor: "#8b70cf",
60	    render() {
61	      const pending = RECS.filter(r => !done()[r._k]);
62	      const recGrid = SP.grid({
63	        id: "recs", agPager: true, pageSize: 20, columns: true, cls: "ag",
64	        toolsBefore: `<label class="switch green"><input type="checkbox" checked data-markets><span class="track"></span>All markets</label>`,
65	        cols: [
66	          { key: "_k", label: "Actions", sort: false, muted: false, fmt: k => `<span class="recacts"><button class="pill" data-fix="${k}">Fix once</button><button class="link-plain" data-ignore="${k}">Ignore</button></span>` },
67	          { key: "opt", label: "Optimiser", filter: true, w: 250, fmt: (v, r) => `<span class="optname">${swatch(r.hue)}<span>${SP.esc(v)}</span></span>` },
68	          { key: "market", label: "Marketplace", filter: true, sort: false },
69	          { key: "kw", label: "Target", filter: true, w: 200, fmt: (v, r) => `<span class="mbadge">${r.match}</span> ${SP.esc(v)}` },
70	          { key: "acos", label: "Current ACOS", filter: true, fmt: v => (v == null ? "" : `${v.toFixed(2)}%`) },
71	          { key: "solution", label: "Solution (Action to execute)", sort: false, w: 230, fmt: v => `<span class="sol">${v}</span>` },
72	          { key: "campaign", label: "Campaign Name", filter: true, w: 220 },
73	          { key: "adgroup", label: "Ad Group Name", filter: true, w: 170 },
74	        ],
75	        rows: pending, empty: "No recommendations right now. They refresh daily.",
76	      });
77	      const ruleGrid = SP.grid({
78	        id: "rules", agPager: true, pageSize: 20, columns: true, check: true, cls: "ag",
79	        toolsBefore: `<button class="btn-soft" data-newrule>${svg(I.plus)}Create new</button>`,
80	        tools: `<div class="anchor"><button class="plain-btn bulk" data-bulk disabled>Bulk edit ${SP.caret}</button></div>`,
81	        cols: [
82	          { key: "_k", label: "Actions", sort: false, fmt: k => `<span class="rowacts"><button class="ic-round" data-editrule="${k}" aria-label="Edit">${svg(I.pencil)}</button><button class="ic-round" data-delrule="${k}" aria-label="Delete">${svg(I.trash)}</button></span>` },
83	          { key: "active", label: "Active", filter: true, fmt: (v, r) => `<label class="switch green mini"><input type="checkbox" ${v ? "checked" : ""} data-active="${r._k}" aria-label="Active"><span class="track"></span></label>` },
84	          { key: "hue", label: "Color", sort: false, fmt: h => swatch(h) },
85	          { key: "name", label: "Optimizer name", filter: true, w: 230 },
86	          { key: "trigger", label: "Trigger condition", sort: false, w: 200, fmt: v => v },
87	          { key: "solution", label: "Solution (Action to execute)", filter: true, w: 230 },
88	          { key: "type", label: "Rule type", filter: true },
89	          { key: "ruleName", label: "Rule name", filter: true, w: 360, fmt: (_, r) => {
90	            const label = r.name.replace(' <=5%', '').replace(' >= 20%', '');
91	            const cut = r.solution.match(/Adjust bid by -(\d+)%/);
92	            const description = cut ? `Cut bids by ${cut[1]}% if ACOS >= ${r.trigger.replace(/[^0-9.]/g, '').replace('.00', '')}% and no adjustment in last 7 days` : /Bad Conversions/.test(r.name) ? `Adjust bids to 20% ACOS for ${/7 days/.test(r.name) ? 'recent ' : ''}bad ads with conversion <= 5% and spend >= $10` : /Good Conversions/.test(r.name) ? 'Move bids towards 40% ACOS for good ads with orders >= 3 and conversion >= 20%' : r.solution;
93	            return `<div class="optimizer-rule"><span class="rule-badge"><span aria-hidden="true">⚒</span>${SP.esc(label)}</span><small>${SP.esc(description)}</small></div>`;
94	          } },
95	        ],
96	        rows: load(RULE_KEY, null) || RULES,
97	      });
98	      const hist = SP.grid({
99	        id: "hist", agPager: true, pageSize: 10, columns: true, check: true, cls: "ag",
100	        toolsBefore: "", tools: `<button class="plain-btn bulk" data-revert disabled>Bulk revert</button>`,
101	        cols: [
102	          { key: "created", label: "Created", filter: true, fmt: v => fmtTime(v) },
103	          { key: "opt", label: "Optimizer Name", w: 200 },
104	          { key: "campaign", label: "Campaign Name", filter: true, w: 200 },
105	          { key: "adgroup", label: "Ad Group Name", filter: true, w: 150 },
106	          { key: "type", label: "Item Type", filter: true },
107	          { key: "kw", label: "Changed Item" },
108	          { key: "plain", label: "Performed Action", w: 200 },
109	          { key: "_k", label: "Restore", sort: false, fmt: k => `<button class="pill sm" data-restore="${k}">Restore</button>` },
110	        ],
111	        rows: [], empty: "No records found.",
112	      });
113	      const histPanel = `${SP.panel(`<div class="frow"><label class="ctl"><span>${svg(SP.ICON.calendar, "cal")}</span><input type="date" data-hfrom value="${SP.iso(SP.addDays(SP.today, -30))}" aria-label="Start date"> - <input type="date" data-hto value="${SP.iso(SP.today)}" aria-label="End date"></label><button class="btn-dark" data-hfilter>Filter</button></div>`)}${hist}`;
114	      return `<div class="actions tight"><a class="btn-outline linkbtn" href="/AdGroupSignals">Manage Signals</a></div>
115	        ${SP.tabs("opt", ["Recommendations", "Manage", "History"], 1, "ant")}${SP.panels("opt", [recGrid, ruleGrid, histPanel], 1)}`;
116	    },
117	    wire(root) {
118	      const g = SP._grids;
119	      const refreshRecs = () => { g.recs.rows = RECS.filter(r => !done()[r._k]); SP.refreshGrid("recs"); };
120	      const refreshHist = () => {
121	        const from = new Date(($("[data-hfrom]", root).value || "2000-01-01") + "T00:00:00").getTime();
122	        const to = new Date(($("[data-hto]", root).value || "2999-01-01") + "T23:59:59").getTime();
123	        const d = done();
124	        g.hist.rows = RECS.filter(r => d[r._k] && d[r._k].action === "fix" && d[r._k].t >= from && d[r._k].t <= to).map(r => ({ ...r, created: d[r._k].t }));
125	        g.hist.checked.clear(); SP.refreshGrid("hist"); $("[data-revert]", root).disabled = true;
126	      };
127	      const saveRules = () => save(RULE_KEY, g.rules.rows);
128	      refreshHist();
129	      const mark = (k, action) => { const d = done(); d[k] = { action, t: Date.now() }; save(OPT_KEY, d); refreshRecs(); refreshHist(); };
130	      const restore = keys => { const d = done(); keys.forEach(k => delete d[k]); save(OPT_KEY, d); refreshRecs(); refreshHist(); };
131	      const ruleEditor = r => SP.modal(r ? "Edit optimizer" : "Create optimizer", `
132	        <label class="field"><span>Optimizer name</span><input name="name" value="${r ? SP.esc(r.name) : ""}" placeholder="e.g. -25% bids if >= 50% ACOS"></label>
