import json,sys,base64,os
b=json.load(open(sys.argv[1]))
eid=sys.argv[2]; out=sys.argv[3]
os.makedirs(out,exist_ok=True)
for r in b['records']:
    if r['id']==eid:
        res=r['result']
        def walk(o,path):
            if isinstance(o,dict):
                for k,v in o.items(): walk(v,path+'.'+k)
            elif isinstance(o,list):
                for i,v in enumerate(o): walk(v,path+f'[{i}]')
            elif isinstance(o,str) and len(o)>2000:
                fn=out+'/'+path.strip('.').replace('/','_')[:100]
                if o.startswith('iVBOR'):
                    open(fn+'.png','wb').write(base64.b64decode(o))
                else: open(fn+'.txt','w').write(o)
                print(path,len(o))
        walk(res,'')
        def strip(o):
            if isinstance(o,dict): return {k:strip(v) for k,v in o.items()}
            if isinstance(o,list): return [strip(v) for v in o]
            if isinstance(o,str) and len(o)>2000: return '<long>'
            return o
        json.dump(strip(res),open(out+'/small.json','w'),indent=1)
