424	      if (sz) { const g = grids[sz.closest("[data-gfoot]").dataset.gfoot]; g.pageSize = +sz.dataset.gsize; g.page = 0; SP.refreshGrid(g.id); return; }
425	      const gc = t.closest("[data-gcols]");
426	      if (gc) {
427	        e.stopPropagation();
428	        const g = grids[gc.dataset.gcols];
429	        SP.popover(gc, g.cols.map(c => ({ label: c.label.replace(/<[^>]+>/g, " ") || c.key, key: c.key, on: !g.hidden.has(c.key) })), (it, on) => { on ? g.hidden.delete(it.key) : g.hidden.add(it.key); SP.refreshGrid(g.id); }, { multi: true });
430	        return;
431	      }
432	      const rng = t.closest("[data-range]");
433	      if (rng) {
434	        e.stopPropagation();
435	        const presets = [["Today", 1], ["Yesterday", 1, 1], ["Last 7 Days", 7], ["Last 14 Days", 14], ["Last 30 Days", 30], ["Last 60 Days", 60], ["Last 90 Days", 90]];
436	        SP.popover(rng, presets.map(([l, d, off]) => ({ label: l, d, off })), it => {
437	          const end = SP.addDays(SP.today, -(it.off || 0)), s = SP.addDays(end, -it.d + 1);
438	          rng.dataset.range = it.d;
439	          SP.$(".rlabel", rng).textContent = it.d === 1 ? `${it.label}: ${SP.shortDate(end)}` : `${it.label}: ${SP.shortDate(s)} - ${SP.shortDate(end)}`;
440	        });
441	        return;
442	      }
443	      const pb = t.closest("[data-products]");
444	      if (pb) {
445	        e.stopPropagation();
446	        pb._sel = pb._sel || new Set();
447	        SP.popover(pb, SP.PRODUCTS.map(p => ({ label: `${p.short} <small>${p.asin}</small>`, p, on: pb._sel.has(p.asin) })), (it, on) => {
448	          on ? pb._sel.add(it.p.asin) : pb._sel.delete(it.p.asin);
449	          const lab = SP.$(".plabel", pb);
450	          lab.textContent = pb._sel.size ? `${pb._sel.size} product${pb._sel.size > 1 ? "s" : ""} selected` : "Select products";
451	          pb.classList.toggle("has", pb._sel.size > 0);
452	        }, { multi: true });
453	        return;
454	      }
455	      const sb = t.closest("[data-select]");
456	      if (sb) {
457	        e.stopPropagation();
458	        const opts = JSON.parse(sb.dataset.select);
459	        SP.popover(sb, opts.map(o => ({ label: o })), it => { SP.$(".slabel", sb).textContent = it.label; sb.classList.add("has"); sb.dataset.value = it.label; });
460	        return;
461	      }
462	      const act = t.closest(".act[data-act='csv']");
463	      if (act) { SP.downloadCSV("export.csv", [["ASIN", "SKU", "Title", "Price"], ...SP.PRODUCTS.map(p => [p.asin, p.sku, p.title, p.price])]); return; }
464	      const ext = t.closest("a[href='#']");
465	      if (ext) e.preventDefault();
466	    });
467	    root.addEventListener("input", e => {
468	      const s = e.target.closest("[data-gsearch]");
469	      if (s) { const g = grids[s.dataset.gsearch]; g.q = s.value; g.page = 0; SP.refreshGrid(g.id); }
470	    });
471	    root.addEventListener("change", e => {
472	      const all = e.target.closest("[data-gall]");
473	      if (all) { const g = grids[all.closest("[data-grid]").dataset.grid]; g.checked = all.checked ? new Set(gridRows(g).map((r, i) => r._k ?? `${i}`)) : new Set(); SP.refreshGrid(g.id); SP.$(`[data-grid="${g.id}"] [data-gall]`).checked = all.checked; return; }
474	      const ck = e.target.closest("[data-gchk]");
475	      if (ck) { const g = grids[ck.closest("[data-grid]").dataset.grid]; ck.checked ? g.checked.add(ck.dataset.gchk) : g.checked.delete(ck.dataset.gchk); return; }
476	      const ps = e.target.closest("[data-gpsize]");
477	      if (ps) { const g = grids[ps.closest("[data-gfoot]").dataset.gfoot]; g.pageSize = +ps.value; g.page = 0; SP.refreshGrid(g.id); return; }
478	      const f = e.target.closest(".file input");
