        if ($(".mg-pop", ms.parentElement)) { $(".mg-pop", ms.parentElement).remove(); return; }
        const t = ms.dataset.ms, list = sigList().filter(s => s.type === t);
        const html = () => `<div class="mg-count"><b>${list.filter(s => st.signals.includes(s._k)).length} ad group signals selected</b></div><div class="mg-plist">${list.map(s => `<label><input type="checkbox" data-sig="${s._k}" ${st.signals.includes(s._k) ? "checked" : ""}>${esc(s.name)}</label>`).join("") || `<div class="mg-none">No data</div>`}</div>`;
