.h-ok svg { width:16px; height:16px; fill:none; stroke:currentColor; stroke-width:2; }
.h-act { display:inline-flex; align-items:center; gap:4px; flex-wrap:wrap; }
.h-ign { color:#adb5bd; }
.h-restore { padding:7px 8px; min-width:100px; }
.h-restore svg { transform:rotate(90deg); }

@media (max-width: 900px) {
  .om-manage .mg { flex-direction:column; }
  .mg-main, .mg-side { width:auto; flex:none; }
  .mg-side { border-left:0; border-top:1px solid #dee2e6; padding:24px; }
  .om-manage .om-foot { flex-wrap:wrap; padding:16px; }
  .om-manage .om-foot .ob { flex:1; width:auto!important; }
  .mg-name { order:-1; flex-basis:100%; justify-content:flex-start; flex-wrap:wrap; }
