}
@media (max-width: 600px) {
  .om-wrap, .om-wrap.top { padding:12px 8px; align-items:flex-start; }
  .mg-rule { flex-direction:column; }
  select.mg-select, .mg-pick { width:100%; flex:none; }
  .mg-pop { width:100%; }
  .rs-row { flex-wrap:wrap; }
  .si-banner { flex-wrap:wrap; }
  .om-foot { flex-wrap:wrap; }
  .au-title b { font-size:16px; }
}
