/* Scale Optimizer: buttons, tags, pop-ups (values from the original's stylesheet). */
.osw { display:inline-flex; width:22px; height:22px; flex:0 0 22px; border-radius:4px; overflow:hidden; vertical-align:middle; }
.osw i { flex:1; }
.otag { display:inline-flex; align-items:center; justify-content:center; height:1.5rem; padding:0 7px; margin-right:8px; font-size:.875rem; line-height:1.5rem; color:#34465e; border:1px solid #34465e; border-radius:4px; background:transparent; white-space:nowrap; }
.ob { height:38px; border-radius:14px; font:inherit; font-size:16px; font-weight:400; line-height:24px; padding:7px 13px; display:inline-flex; align-items:center; justify-content:center; gap:6px; cursor:pointer; white-space:nowrap; border:1px solid transparent; background:transparent; color:#212529; }
.ob svg { width:16px; height:16px; fill:none; stroke:currentColor; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; }
.ob.bold { font-weight:700; }
.ob-main { background:#34465e; color:#fff; border-color:#395070; }
.ob-main:hover { background:#395070; }
.ob-outline { outline:1px solid #2c3a4f; outline-offset:-1px; }
.ob-outline:hover { border-color:#2c3a4f; }
.ob-outline:active { background:#f5f5f7; }
.ob-sec { background:#e4e7eb; border-color:#ced4da; }
.ob-sec:hover { background:#dadee3; }
.ob-grey { border-color:#ced4da; }
.ob-grey:hover, .ob-grey:focus-visible { border-color:#34465e; }
.ob-danger { background:#dc3545; color:#fff; border-color:#dc3545; }
.ob-danger:active { background:#c42937; }
.ob-plain:active { background:#f5f6f7; }
.dgrey { color:#6c757d; }

.page-optimizer .recacts { display:inline-flex; align-items:center; gap:4px; }
.page-optimizer [data-grid="recs"] tbody tr[data-k] { cursor:pointer; }
.page-optimizer [data-grid="recs"] tbody tr[data-k]:hover { background:#f1f3f4; }
.page-optimizer .optname { display:flex; align-items:center; gap:8px; white-space:normal; }
.page-optimizer [data-panel="2"] .grid-tools > .bulk { order:2; padding:0 24px 0 12px; border-right:1px solid #dee2e6; border-radius:0; }
.page-optimizer [data-panel="2"] .grid-tools > .anchor:has([data-gcols]) { order:3; }
.page-optimizer .bulk b { margin:0 3px; }

/* Rule badge (links to the rule, criteria on hover) */
.rule-badge { position:relative; display:inline-flex; align-items:center; gap:4px; padding:4px 10px; border:1px solid #ced4da; border-radius:14px; background:#fff; color:#212529; font-size:15px; line-height:130%; text-decoration:none; text-align:left; }
.rule-badge:hover { background:#f3f4f6; border-color:#34465e; color:#212529; text-decoration:none; }
.rule-badge .rb-ic { color:#45a19c; display:inline-flex; }
.rule-badge svg { width:16px; height:16px; fill:none; stroke:currentColor; stroke-width:1.7; stroke-linecap:round; stroke-linejoin:round; }
.rule-badge:hover .rb-ic { color:#212529; }
.rb-name { white-space:normal; word-break:break-word; }
.rb-tip { display:none; position:absolute; z-index:40; left:0; bottom:calc(100% + 8px); min-width:240px; max-width:320px; padding:10px 14px; border-radius:8px; background:rgba(0,0,0,.85); color:#fff; font-size:13px; line-height:1.5; grid-template-columns:auto 1fr; column-gap:12px; white-space:normal; box-shadow:0 6px 16px rgba(0,0,0,.12); }
.rb-tip b { grid-column:1 / -1; display:flex; align-items:center; gap:6px; padding-bottom:6px; margin-bottom:6px; border-bottom:1px solid #6c757d; }
.rb-tip b svg { color:#45a19c; }
.rb-tip em { grid-column:1 / -1; font-style:normal; color:#ced4da; margin-top:6px; }
.rule-badge:hover .rb-tip, .rule-badge:focus-visible .rb-tip, .si-stats:hover .rb-tip, .si-stats:focus .rb-tip { display:grid; }

/* ---------- Dialogs ---------- */
body.om-lock { overflow:hidden; }
.om-wrap { position:fixed; inset:0; z-index:3000; background:rgba(0,0,0,.75); display:flex; align-items:center; justify-content:center; padding:20px; overflow:auto; font-family:Roboto, Arial, sans-serif; color:#212529; }
.om-wrap.top { align-items:flex-start; padding-top:100px; }
.om { background:#fff; border-radius:14px; box-shadow:0 6px 16px rgba(0,0,0,.08), 0 9px 28px 8px rgba(0,0,0,.05); display:flex; flex-direction:column; max-width:100%; font-size:15px; line-height:1.5; margin:auto 0; }
.om-wrap.top .om { margin:0 0 auto; }
.om-head { display:flex; align-items:center; gap:.75rem; padding:1rem 1.5rem; border-bottom:1px solid #dee2e6; border-radius:14px 14px 0 0; }
.om-title { font-size:20px; font-weight:500; line-height:1.4; }
.om-div { width:1px; height:20px; background:#dee2e6; }
.om-sub { color:#6c757d; }
.om-x { margin-left:auto; border:0; background:none; color:#6c757d; font-size:16px; width:28px; height:28px; border-radius:6px; cursor:pointer; flex:0 0 28px; }
.om-x:hover { background:#f2f4f5; color:#212529; }
.om-foot { display:flex; justify-content:space-between; align-items:center; gap:8px; padding:1rem 1.25rem; background:#f8f9fa; border-top:1px solid #dee2e6; border-radius:0 0 14px 14px; }
.om-right { display:flex; gap:8px; }
.om-pair { display:flex; gap:16px; width:100%; }
.om-pair .ob { flex:1; }
.om-pad { padding:24px; font-size:16px; }
.om-pad.big { font-size:18px; }
.om-status { display:flex; flex-direction:column; align-items:center; text-align:center; gap:8px; padding:32px 24px; font-size:16px; }
.om-status .om-sico { width:56px; height:56px; fill:none; stroke-width:1.4; }
.om-status.success .om-sico { stroke:#189771; }
.om-status.fail .om-sico { stroke:#dc3545; }
.om-sdet { color:#6c757d; font-size:14px; }
.om-loader { width:100%; display:flex; justify-content:center; padding:7px 0; }
.om-loader i { width:8px; height:8px; border-radius:50%; background:#34465e; animation:om-pulse .4s infinite linear alternate; }
@keyframes om-pulse { from { box-shadow:14px 0 #34465e, -14px 0 #34465e33; background:#34465e33; } to { box-shadow:14px 0 #34465e33, -14px 0 #34465e; background:#34465e; } }

/* Details */
.dcard { padding:16px 20px; display:flex; flex-direction:column; gap:8px; }
.dtitle { font-size:18px; font-weight:600; }
.dkw { display:flex; align-items:center; flex-wrap:wrap; }
.dstat-v { display:flex; gap:6px; }
.dstat.last { display:flex; justify-content:space-between; align-items:center; }
.dmore, .dtoggle { display:inline-flex; align-items:center; gap:6px; border:0; background:none; padding:0; color:#6c757d; font:inherit; cursor:pointer; user-select:none; }
.dmore svg, .dtoggle svg { width:12px; height:12px; fill:none; stroke:currentColor; stroke-width:2.4; transition:transform .2s; }
svg.rot-down { transform:rotate(90deg); }
svg.rot-up { transform:rotate(270deg); }
.dbody { padding:16px 20px; display:flex; flex-direction:column; gap:24px; }
.dbox { border:1px solid #ced4da; border-radius:14px; }
.dsec { display:flex; flex-direction:column; gap:8px; padding:16px 20px; }
.dsec + .dsec { border-top:1px solid #ced4da; gap:4px; }
.drow { display:flex; justify-content:space-between; align-items:center; }
.dhead { font-size:15px; font-weight:700; }
.dlines { display:flex; flex-direction:column; gap:4px; }
.dlines[hidden], .dcalc[hidden] { display:none; }
.dcalc { display:flex; flex-direction:column; gap:4px; border-top:1px solid #ced4da; margin-top:8px; padding-top:8px; }
.dmeta { display:flex; flex-direction:column; gap:10px; }
.dline { display:flex; align-items:center; flex-wrap:wrap; }
.dline .dgrey { margin-right:6px; }
.dgrey-ic { width:16px; height:16px; margin-right:6px; fill:none; stroke:#6c757d; stroke-width:1.6; }
.dlink { color:inherit; text-decoration:underline; cursor:pointer; }

/* Resolved */
.rs-primary { background:#faffef; padding:24px; display:flex; flex-direction:column; gap:24px; align-items:flex-start; }
.rs-line { display:flex; align-items:center; gap:8px; }
.rs-ok { width:20px; height:20px; flex:0 0 20px; fill:none; stroke:#189771; stroke-width:2; }
.rs-kw { font-size:15px; line-break:anywhere; }
.rs-auto { background:linear-gradient(74deg,#53dfff 35.11%,#6996ff 90.66%); padding:16px 20px; display:flex; align-items:center; gap:8px; }
.rs-auto.col { flex-direction:column; align-items:stretch; }
.rs-row { display:flex; align-items:center; gap:8px; }
.rs-col { display:flex; flex-direction:column; }
.rs-col b { font-size:16px; line-height:140%; }
.rs-q { font-size:16px; width:154px; line-height:140%; }
