content.content:
196	          <span class="hint">${svg('<circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8v.2"/>')}Recommendations refresh daily.</span>
197	        </div>
198	        <div class="section-body"><div class="opt-cards">${RECS.map(recHTML).join("")}</div></div>
199	      </section>
200	
201	      <section class="section" id="sec-perf">
202	        <div class="section-head">
203	          <button class="collapse" aria-label="Collapse Performance & activity" aria-expanded="true"></button>
204	          <h2>Performance &amp; activity</h2>
205	        </div>
206	        <div class="section-body">
207	          <div class="chart-controls">
208	            <div class="chips" id="chips"></div>
209	            <div class="seg" id="bucket">
210	              <button data-b="days" class="on">Days</button><button data-b="weeks">Weeks</button><button data-b="months" disabled>Months</button>
211	            </div>
212	          </div>
213	          <svg class="chart" id="chart" role="img" aria-label="Performance chart"></svg>
214	          <div class="legend"><span style="--c:#f5c242">Rule/Strategy assigned</span><span style="--c:#f39c34">Rule/Strategy edited</span></div>
215	        </div>
216	      </section>
217	
218	      <div class="tabs-wrap">
219	        <div class="tabs" role="tablist" id="tabs">
220	          ${[["today", "Today"], ["yesterday", "Yesterday"], ["d7", "7 Days"], ["d14", "14 Days"], ["d30", "30 Days"], ["bydate", "Sales by date"], ["fees", "Account-level fees"]]
221	            .map(([k, l]) => `<button role="tab" data-tab="${k}" class="${k === state.tab ? "on" : ""}">${l}</button>`).join("")}
222	        </div>
223	        <div class="grid-tools">
224	          <label class="instant">${svg('<circle cx="10.5" cy="10.5" r="6.5"/><path d="M15.5 15.5L20 20"/>')}<input id="instant" placeholder="Instant search" aria-label="Instant search"></label>
225	          <button class="plain-btn">${svg('<rect x="3" y="5" width="18" height="14" rx="1.5"/><path d="M9 5v14M15 5v14"/>')}Columns</button>
226	          <button class="btn-dark" id="download">Download</button>
227	        </div>
228	        <div class="table-scroll"><table id="grid"></table></div>
229	        <div class="grid-foot" id="grid-foot"></div>
230	        <div class="updated">Updated just now - Processed: 0 ms</div>
231	      </div>`;
232	  }
233	
234	  // ---------- Chart ----------
235	  const SERIES = [
236	    { key: "tacos", label: "TACOS", color: "#8b7fe0", dashed: true, axis: "pct" },
237	    { key: "ppc", label: "PPC Sales", color: "#5a64b8", axis: "usd" },
238	    { key: "organic", label: "Organic sales", color: "#45b7cf", axis: "usd" },
239	  ];
240	  // deterministic pseudo-random sample series
241	  function sample(seed, n, lo, hi, gaps) {
242	    let s = seed; const out = [];
243	    for (let i = 0; i < n; i++) {
244	      s = (s * 9301 + 49297) % 233280;
245	      const v = lo + (s / 233280) * (hi - lo);
246	      out.push(gaps && gaps.includes(i) ? null : Math.round(v));
247	    }
248	    return out;
249	  }
250	  const DAYS = 30;
251	  const RAW = {
252	    tacos: sample(7, DAYS, 30, 140, [0, 9, 10, 11, 12, 23, 24, 25, 26, 27]),
253	    ppc: sample(3, DAYS, 0, 140),
254	    organic: sample(11, DAYS, 0, 110),
255	  };
256	  RAW.organic[18] = 760; RAW.tacos[28] = 230; RAW.tacos[29] = 175;
257	
258	  function drawChart() {
259	    const el = $("#chart"); if (!el) return;
260	    const W = el.clientWidth || 1300, H = el.clientHeight || 435;
261	    const L = 90, R = 20, T = 10, B = 60;
262	    const weekly = state.bucket === "weeks";
263	    const labels = [], data = {};
264	    for (const s of SERIES) data[s.key] = [];
265	    if (weekly) {
266	      for (let w = 0; w < DAYS; w += 7) {
267	        labels.push(addDays(today, -DAYS + w));
268	        for (const s of SERIES) {
269	          const chunk = RAW[s.key].slice(w, w + 7).filter(v => v != null);
270	          const v = chunk.length ? chunk.reduce((a, b) => a + b, 0) / (s.axis === "pct" ? chunk.length : 1) : null;
271	          data[s.key].push(v);
272	        }
273	      }
274	    } else {
275	      for (let i = 0; i < DAYS; i++) labels.push(addDays(today, -DAYS + i));
276	      for (const s of SERIES) data[s.key] = RAW[s.key];
277	    }
278	    const usdMax = weekly ? 2000 : 1000, pctMax = 250;
279	    const n = labels.length;
280	    const x = i => L + (n === 1 ? 0 : (i * (W - L - R)) / (n - 1));
281	    const plotH = H - T - B;
282	    const y = (v, axis) => T + plotH - (v / (axis === "pct" ? pctMax : usdMax)) * plotH * 0.84 - plotH * 0.08;
283	    let out = "";
284	    for (let k = 0; k <= 5; k++) {
285	      const yy = y((usdMax * k) / 5, "usd");
286	      out += `<line x1="${L}" x2="${W - R}" y1="${yy}" y2="${yy}" stroke="#eceef1" stroke-width="1"/>`;
287	      out += `<text x="${L - 58}" y="${yy + 4}" text-anchor="end">${k === 5 ? `$${usdMax / 1000}k` : `$${(usdMax * k) / 5}`}</text>`;
288	      out += `<text x="${L - 14}" y="${yy + 4}" text-anchor="end">${(pctMax * k) / 5}%</text>`;
289	    }
290	    out += `<text x="${L - 14}" y="${T + plotH + 4}" text-anchor="end">0</text>`;
291	    out += `<line x1="${L}" x2="${W - R}" y1="${T + plotH}" y2="${T + plotH}" stroke="#dfe2e6"/>`;
292	    labels.forEach((d, i) => {
293	      if (n > 15 && W < 700 && i % 3) return;
294	      out += `<text transform="translate(${x(i)},${H - 28}) rotate(-25)" text-anchor="end">${d.getMonth() + 1}/${d.getDate()}</text>`;
295	    });
296	    for (const s of SERIES) {
297	      if (!state.series[s.key]) continue;
298	      let path = "", pen = false;
299	      data[s.key].forEach((v, i) => {
300	        if (v == null) { pen = false; return; }
301	        path += `${pen ? "L" : "M"}${x(i).toFixed(1)},${y(v, s.axis).toFixed(1)}`; pen = true;
302	      });
303	      out += `<path d="${path}" stroke="${s.color}" stroke-width="1.6" fill="none" ${s.dashed ? 'stroke-dasharray="3 3"' : ""}/>`;
304	    }
305	    el.setAttribute("viewBox", `0 0 ${W} ${H}`);
306	    el.innerHTML = out;
307	  }
308	
309	  function renderChips() {
310	    const chips = $("#chips");
311	    chips.innerHTML = `<select class="metric-select" aria-label="Preset"><option>Custom</option><option>Sales</option><option>Advertising</option></select>` +
312	      SERIES.filter(s => state.series[s.key]).map(s => `
313	        <span class="chip"><span class="swatch ${s.dashed ? "dashed" : ""}" style="border-top-color:${s.color}"></span>${s.label}<button data-rm="${s.key}" aria-label="Remove ${s.label}">✕</button></span>`).join("") +
314	      `<div class="anchor"><button class="chip-add" id="chip-add" aria-label="Add metric">+</button></div>`;
315	  }
316	
317	  // ---------- Table ----------
318	  const COLS = [
319	    ["orders", "Orders"], ["units", "Units"], ["sales", "Sales", "usd"], ["profits", "Profits", "usd"], ["ads", "Ads", "usd"], ["acos", "ACOS", "pct2"], ["tacos", "TACOS", "pct"],
320	    ["organic", "Organic Units"], ["promo", "Promo Units"], ["ppcSales", "PPC Sales", "usd"], ["ppcOrders", "PPC Orders"], ["ppcUnits", "PPC Units"],
321	    ["roi", "ROI", "pct"], ["margin", "Margin", "pct"], ["velocity", "Velocity"], ["payout", "Payout", "usd"], ["plUnit", "P&L Per Unit", "usd"],
322	  ];
323	  const fmt = (v, t) => (v === 0 && t !== "usd" && t !== "pct" && t !== "pct2" ? "" : t === "usd" ? money(v) : t === "pct" ? pct(v) : t === "pct2" ? (v ? `${v.toFixed(2)}%` : "") : String(v));
324	
325	  function rowsFor(tab) {
326	    const [mult, count, offset] = PERIOD_SCALE[tab];
327	    if (!count) return [];
328	    return PRODUCTS.slice(0, Math.min(PRODUCTS.length, count)).map((p, i) => {
329	      const k = i === 0 ? mult : Math.max(1, Math.round(mult * (0.6 - i * 0.15) + offset * 0.2));
330	      const r = { ...p };
331	      for (const [key] of COLS) {
332	        const b = p.base[key];
333	        r[key] = ["acos", "tacos", "roi", "margin"].includes(key) ? b : ["sales", "profits", "ads", "ppcSales", "payout"].includes(key) ? Math.round(b * k * 100) / 100 : key === "plUnit" ? b : key === "velocity" ? b : Math.round(b * k);
334	      }
335	      return r;
336	    });
337	  }
338	
339	  function renderTable() {
340	    const grid = $("#grid"); if (!grid) return;
341	    let rows = rowsFor(state.tab);
342	    const q = state.query.trim().toLowerCase();
343	    if (q) rows = rows.filter(r => `${r.title} ${r.id} ${r.sku}`.toLowerCase().includes(q));
344	    const { key, dir } = state.sort;
345	    rows.sort((a, b) => (a[key] - b[key]) * dir);
346	    const sum = {};
347	    for (const [k] of COLS) sum[k] = rows.reduce((a, r) => a + r[k], 0);
348	    if (rows.length) {
349	      sum.acos = sum.ppcSales ? (sum.ads / sum.ppcSales) * 100 : 0;
350	      sum.tacos = sum.sales ? (sum.ads / sum.sales) * 100 : 0;
351	      sum.roi = rows.reduce((a, r) => a + r.roi, 0) / rows.length;
352	      sum.margin = sum.sales ? (sum.profits / sum.sales) * 100 : 0;
353	      sum.plUnit = sum.units ? sum.profits / sum.units : 0;
354	    }
355	    const cell = (r, k, t) => {
356	      const v = r[k], neg = typeof v === "number" && v < 0 && (k === "profits" || k === "payout" || k === "plUnit" || k === "roi" || k === "margin");
357	      const red = k === "ads" && v ? "neg" : "";
358	      if (k === "profits") return `<td class="profit"><span class="dash-u ${neg ? "neg" : "pos-sales"}">${fmt(v, t)}</span></td>`;
359	      return `<td class="${neg ? "neg" : red}">${fmt(v, t)}</td>`;
360	    };
361	    grid.innerHTML = `
362	      <thead><tr>
363	        <th class="l" style="cursor:default">Product<span class="arrow">↓</span></th><th class="l" style="cursor:default">Title<span class="arrow">↓</span></th>
364	        ${COLS.map(([k, l]) => `<th data-sort="${k}" class="${key === k ? "sorted" : ""}">${l}<span class="arrow">${key === k ? (dir < 0 ? "↓" : "↑") : "↓"}</span></th>`).join("")}
365	      </tr></thead>
366	      <tbody>
367	        ${rows.length ? `<tr class="sum"><td class="l" colspan="2">▾ Sum</td>${COLS.map(([k, , t]) => cell(sum, k, t)).join("")}</tr>` : ""}
368	        ${rows.map(r => `<tr>
369	          <td class="l"><div class="thumb"></div></td>
370	          <td class="title-cell"><div>${r.title}</div><small><a href="/Products">${r.id}</a>, ${r.sku}, Stock: ${r.stock} , ${r.supply} Supply</small></td>
371	          ${COLS.map(([k, , t]) => cell(r, k, t)).join("")}
372	        </tr>`).join("")}
373	        ${rows.length ? "" : `<tr><td class="l" colspan="${COLS.length + 2}" style="color:var(--muted)">No records for this period.</td></tr>`}
374	      </tbody>`;
375	    $("#grid-foot").textContent = rows.length ? `Items 1 to ${rows.length} of ${rows.length}` : "No items to display";
376	  }
377	
378	  function wireDashboard() {
379	    const ranges = [[1, "Today"], [7, "Last 7 days"], [14, "Last 14 days"], [30, "Last 30 days"], [60, "Last 60 days"], [90, "Last 90 days"]];
380	    $("#date-btn").addEventListener("click", e => {
381	      e.stopPropagation();
382	      popover(e.currentTarget, ranges.map(([d, l]) => ({ d, label: l, on: d === state.range })), it => {
383	        state.range = it.d;
384	        $("#date-label").textContent = `${shortDate(addDays(today, -it.d + 1))} - ${shortDate(today)}`;
385	      });
386	    });
387	    $("#product-btn").addEventListener("click", e => {
388	      e.stopPropagation();
389	      popover(e.currentTarget, [{ label: "All products", id: null }, ...PRODUCTS.map(p => ({ label: p.title, id: p.id, on: state.products.includes(p.id) }))], it => {
390	        state.products = it.id ? [it.id] : [];
391	        const lbl = $("#product-label");
392	        lbl.textContent = it.id ? it.label : "Select products";
393	        lbl.style.color = it.id ? "var(--body)" : "";
394	      });
395	    });
396	    $("#apply").addEventListener("click", () => {
397	      const pick = state.products[0];
398	      state.query = pick ? PRODUCTS.find(p => p.id === pick).title : "";
399	      $("#instant").value = state.query;
400	      renderTable();
401	    });
402	
403	    $$(".collapse").forEach(b => b.addEventListener("click", () => {
404	      const body = b.closest(".section").querySelector(".section-body");
405	      body.hidden = !body.hidden;
406	      b.classList.toggle("closed", body.hidden);
407	      b.setAttribute("aria-expanded", String(!body.hidden));
408	      if (!body.hidden) drawChart();
409	    }));
410	
411	    $(".opt-cards").addEventListener("click", e => {
412	      const card = e.target.closest(".opt-card"); if (!card) return;
413	      if (e.target.closest(".fix")) {
414	        card.classList.add("fixed");
415	        card.querySelector(".opt-head").textContent = "Fixed — keyword negated";
416	        e.target.closest(".fix").disabled = true;
417	      } else if (e.target.closest(".details")) {
418	        const r = RECS[+card.dataset.rec];
419	        alert(`${r.term}\n${r.clicks} clicks, ${r.orders} orders in the last 30 days.\nSuggested: add as negative exact.`);
420	      }
421	    });
422	
423	    $("#chips").addEventListener("click", e => {
424	      const rm = e.target.closest("[data-rm]");
425	      if (rm) { state.series[rm.dataset.rm] = false; renderChips(); drawChart(); return; }
426	      const add = e.target.closest("#chip-add");
427	      if (add) {
428	        e.stopPropagation();
429	        const hidden = SERIES.filter(s => !state.series[s.key]);
430	        popover(add, hidden.length ? hidden.map(s => ({ label: s.label, key: s.key })) : [{ label: "All metrics shown" }], it => {
431	          if (it.key) { state.series[it.key] = true; renderChips(); drawChart(); }
432	        });
433	      }
434	    });
435	    $("#bucket").addEventListener("click", e => {
436	      const b = e.target.closest("button[data-b]"); if (!b || b.disabled) return;
437	      state.bucket = b.dataset.b;
438	      $$("#bucket button").forEach(x => x.classList.toggle("on", x === b));
439	      drawChart();
440	    });
441	
442	    $("#tabs").addEventListener("click", e => {
443	      const t = e.target.closest("[data-tab]"); if (!t) return;
444	      state.tab = t.dataset.tab;
445	      $$("#tabs button").forEach(x => x.classList.toggle("on", x === t));
446	      renderTable();
447	    });
448	    $("#grid").addEventListener("click", e => {
449	      const th = e.target.closest("th[data-sort]"); if (!th) return;
450	      const k = th.dataset.sort;
