.pc-left { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.pc-chips { display:flex; align-items:center; gap:8px; flex-wrap:wrap; }
.pc-preset { position:relative; }
.pc-preset-btn { width:140px; height:38px; display:inline-flex; align-items:center; justify-content:space-between; padding:0 11px; border:1px solid #ced4da; border-radius:14px; background:#fff; font:inherit; font-size:16px; color:#212529; cursor:pointer; white-space:nowrap; }
.pc-preset-btn:hover { border-color:#adb5bd; }
