          ${COLS.map(([k, , t]) => cell(r, k, t)).join("")}
        </tr>`).join("")}
        ${rows.length ? "" : `<tr><td class="l" colspan="${COLS.length + 2}" style="color:var(--muted)">No records for this period.</td></tr>`}
